/**
 * 平台端附件管理 API
 * 对接后端 /admin/attachments/* 接口
 *
 * @module api/admin/attachment
 */
import type {
  AttachmentInfo,
  AttachmentInfoRaw,
  AttachmentListParams,
  AttachmentStats,
  AttachmentStatsByTenant,
  AttachmentUrlResult,
} from '#/types/attachment';
import type { PaginatedResponse, SelectOption } from '#/types/query';
import type { ApiRequestOptions } from '#/utils/request';

import { inferCategory } from '#/types/attachment';
import { requestClient } from '#/utils/request';

// ============================================================
// 转换函数
// ============================================================

/** 将后端 snake_case 转换为前端 camelCase */
function transformAttachmentInfo(raw: AttachmentInfoRaw): AttachmentInfo {
  return {
    id: raw.id,
    tenantId: raw.tenant_id,
    name: raw.name,
    originalName: raw.original_name,
    path: raw.path,
    size: raw.size,
    hash: raw.hash,
    mimeType: raw.mime_type,
    extension: raw.extension,
    visibility: raw.visibility,
    driver: raw.driver,
    baseUrl: raw.base_url,
    status: raw.status,
    source: raw.source,
    uploaderId: raw.uploader_id,
    businessType: raw.business_type,
    businessId: raw.business_id,
    meta: raw.meta,
    category: inferCategory(raw.mime_type),
    createdAt: raw.created_at,
    updatedAt: raw.updated_at,
  };
}

// ============================================================
// 类型定义
// ============================================================

/** 附件列表响应 */
export interface AttachmentListResponse {
  items: AttachmentInfo[];
  total: number;
  page: number;
  page_size: number;
}

// ============================================================
// API 接口
// ============================================================

const API_PREFIX = '/admin/attachments';

/**
 * 获取附件列表
 * GET /admin/attachments
 *
 * 权限: attachment:list
 * 支持按企业筛选: filter[tenant_id][eq]=1
 */
export async function getAttachmentListApi(
  params?: AttachmentListParams,
  options?: ApiRequestOptions,
): Promise<AttachmentListResponse> {
  const response = await requestClient.get<
    PaginatedResponse<AttachmentInfoRaw>
  >(API_PREFIX, { params, ...options });

  return {
    items: response.items.map((item) => transformAttachmentInfo(item)),
    total: response.total,
    page: response.page,
    page_size: response.page_size,
  };
}

/**
 * 获取附件详情
 * GET /admin/attachments/{attachment_id}
 *
 * 权限: attachment:detail
 */
export async function getAttachmentDetailApi(
  attachmentId: number,
  options?: ApiRequestOptions,
): Promise<AttachmentInfo> {
  const raw = await requestClient.get<AttachmentInfoRaw>(
    `${API_PREFIX}/${attachmentId}`,
    options,
  );
  return transformAttachmentInfo(raw);
}

/**
 * 删除附件
 * DELETE /admin/attachments/{attachment_id}
 *
 * 权限: attachment:delete
 */
export async function deleteAttachmentApi(
  attachmentId: number,
  options?: ApiRequestOptions,
): Promise<void> {
  await requestClient.delete(`${API_PREFIX}/${attachmentId}`, options);
}

/**
 * 获取附件下拉选项
 * GET /admin/attachments/select
 */
export async function getAttachmentSelectApi(
  params?: Record<string, unknown>,
  options?: ApiRequestOptions,
): Promise<SelectOption[]> {
  const response = await requestClient.get<{ items: SelectOption[] }>(
    `${API_PREFIX}/select`,
    { params, ...options },
  );
  return response.items;
}

/**
 * 获取附件统计
 * GET /admin/attachments/stats
 */
export async function getAttachmentStatsApi(
  params?: Record<string, unknown>,
  options?: ApiRequestOptions,
): Promise<AttachmentStats> {
  return requestClient.get<AttachmentStats>(`${API_PREFIX}/stats`, {
    params,
    ...options,
  });
}

/**
 * 获取按企业分组的附件统计
 * GET /admin/attachments/stats/by-tenant
 */
export async function getAttachmentStatsByTenantApi(
  params?: Record<string, unknown>,
  options?: ApiRequestOptions,
): Promise<AttachmentStatsByTenant[]> {
  const response = await requestClient.get<{
    items: AttachmentStatsByTenant[];
  }>(`${API_PREFIX}/stats/by-tenant`, { params, ...options });
  return response.items;
}

/**
 * 获取下载链接
 * GET /admin/attachments/{attachment_id}/download-url
 */
export async function getAttachmentDownloadUrlApi(
  attachmentId: number,
  params?: { expires?: number },
  options?: ApiRequestOptions,
): Promise<AttachmentUrlResult> {
  return requestClient.get<AttachmentUrlResult>(
    `${API_PREFIX}/${attachmentId}/download-url`,
    { params, ...options },
  );
}

/**
 * 获取预览链接
 * GET /admin/attachments/{attachment_id}/preview-url
 */
export async function getAttachmentPreviewUrlApi(
  attachmentId: number,
  params?: { expires?: number },
  options?: ApiRequestOptions,
): Promise<AttachmentUrlResult> {
  return requestClient.get<AttachmentUrlResult>(
    `${API_PREFIX}/${attachmentId}/preview-url`,
    { params, ...options },
  );
}

// ============================================================
// 上传接口
// ============================================================

/** 上传附件响应（后端返回嵌套结构） */
export interface AdminUploadAttachmentResponse {
  attachment: AttachmentInfoRaw;
  url: string;
  used_bytes: number;
}

/**
 * 上传附件（平台端）
 * POST /admin/attachments/upload
 *
 * 权限: attachment:upload
 */
export async function uploadAttachmentApi(
  params: {
    business_id?: number;
    business_type?: string;
    file: Blob | File;
    tenant_id?: number;
    visibility?: 'private' | 'public';
  },
  onProgress?: (progress: { percent: number }) => void,
  options?: ApiRequestOptions,
): Promise<AdminUploadAttachmentResponse> {
  const {
    file,
    tenant_id = 0,
    visibility = 'private',
    business_type,
    business_id,
  } = params;
  const uploadData: { [key: string]: Blob | File | string; file: Blob | File } =
    { file };
  uploadData.tenant_id = String(tenant_id);
  if (visibility) uploadData.visibility = visibility;
  if (business_type) uploadData.business_type = business_type;
  if (business_id) uploadData.business_id = String(business_id);

  return requestClient.upload<AdminUploadAttachmentResponse>(
    `${API_PREFIX}/upload`,
    uploadData,
    {
      ...options,
      onUploadProgress: onProgress
        ? (progressEvent) => {
            const percent = progressEvent.total
              ? Math.round((progressEvent.loaded * 100) / progressEvent.total)
              : 0;
            onProgress({ percent });
          }
        : undefined,
    },
  );
}

/**
 * 邮件日志 API
 * 对接后端 /admin/email-logs/* 接口
 */
import type { ApiRequestOptions } from '#/utils/request';

import { requestClient } from '#/utils/request';

const API_PREFIX = '/admin/email-logs';

/** 邮件日志信息（后端原始 snake_case） */
interface EmailLogInfoRaw {
  id: number;
  to_address: string;
  cc: null | string;
  bcc: null | string;
  subject: string;
  status: string;
  triggered_by: string;
  error_message: null | string;
  sent_at: null | string;
  tenant_id: null | number;
  created_at: string;
}

/** 邮件日志信息（前端 camelCase） */
export interface EmailLogInfo {
  id: number;
  toAddress: string;
  cc: null | string;
  bcc: null | string;
  subject: string;
  status: string;
  triggeredBy: string;
  errorMessage: null | string;
  sentAt: null | string;
  tenantId: null | number;
  createdAt: string;
}

/** 手动发送邮件请求 */
export interface EmailSendRequest {
  to: string[];
  subject: string;
  html_body?: null | string;
  text_body?: null | string;
  cc?: null | string[];
  bcc?: null | string[];
}

/** 测试邮件请求 */
export interface EmailTestRequest {
  to: string;
}

/** 发送结果 */
export interface EmailSendResult {
  success: boolean;
  message: string;
  error: null | string;
}

/** 邮件日志详情（含 body） */
export interface EmailLogDetail {
  id: number;
  toAddress: string;
  cc: null | string;
  bcc: null | string;
  subject: string;
  status: string;
  triggeredBy: string;
  htmlBody: null | string;
  textBody: null | string;
  errorMessage: null | string;
  sentAt: null | string;
  tenantId: null | number;
  createdAt: null | string;
}

/** 分页响应 */
export interface EmailLogListResponse {
  items: EmailLogInfo[];
  total: number;
  page: number;
  page_size: number;
}

function transformEmailLogInfo(raw: EmailLogInfoRaw): EmailLogInfo {
  return {
    id: raw.id,
    toAddress: raw.to_address,
    cc: raw.cc,
    bcc: raw.bcc,
    subject: raw.subject,
    status: raw.status,
    triggeredBy: raw.triggered_by,
    errorMessage: raw.error_message,
    sentAt: raw.sent_at,
    tenantId: raw.tenant_id,
    createdAt: raw.created_at,
  };
}

/**
 * 获取邮件日志列表
 */
export async function getEmailLogListApi(
  params?: Record<string, unknown>,
  options?: ApiRequestOptions,
): Promise<EmailLogListResponse> {
  const response = await requestClient.get<{
    items: EmailLogInfoRaw[];
    page: number;
    page_size: number;
    total: number;
  }>(API_PREFIX, { params, ...options });

  return {
    items: response.items.map(transformEmailLogInfo),
    total: response.total,
    page: response.page,
    page_size: response.page_size,
  };
}

/**
 * 获取邮件日志详情（含 body）
 */
export async function getEmailLogDetailApi(
  id: number,
  options?: ApiRequestOptions,
): Promise<EmailLogDetail> {
  const raw = await requestClient.get<Record<string, unknown>>(
    `${API_PREFIX}/${id}`,
    options,
  );
  return {
    id: raw.id as number,
    toAddress: raw.to_address as string,
    cc: raw.cc as null | string,
    bcc: raw.bcc as null | string,
    subject: raw.subject as string,
    status: raw.status as string,
    triggeredBy: raw.triggered_by as string,
    htmlBody: raw.html_body as null | string,
    textBody: raw.text_body as null | string,
    errorMessage: raw.error_message as null | string,
    sentAt: raw.sent_at as null | string,
    tenantId: raw.tenant_id as null | number,
    createdAt: raw.created_at as null | string,
  };
}

/**
 * 手动发送邮件
 */
export async function sendEmailApi(
  data: EmailSendRequest,
  options?: ApiRequestOptions,
): Promise<EmailSendResult> {
  return requestClient.post<EmailSendResult>(
    `${API_PREFIX}/send`,
    data,
    options,
  );
}

/**
 * 发送测试邮件
 */
export async function sendTestEmailApi(
  data: EmailTestRequest,
  options?: ApiRequestOptions,
): Promise<EmailSendResult> {
  return requestClient.post<EmailSendResult>(
    `${API_PREFIX}/test`,
    data,
    options,
  );
}

/**
 * 公开配置 API
 * 获取平台/企业公开配置，无需认证
 */
import { getProcessedImageUrl } from '#/utils/image';
import { baseRequestClient } from '#/utils/request';

/**
 * 将附件 ID 字符串转为图片访问 URL
 * 配置项存储的是附件 ID（如 "10"），需转为 /api/public/attachments/{id}/image
 */
function attachmentIdToUrl(idStr: string | undefined): string | undefined {
  if (!idStr) return undefined;
  const id = Number(idStr);
  if (!Number.isFinite(id) || id <= 0) return idStr;
  return getProcessedImageUrl(id);
}

// ============================================================
// 类型定义
// ============================================================

/** 品牌配置 */
export interface BrandConfig {
  /** 站点名称 */
  siteName?: string;
  /** 站点描述 */
  siteDescription?: string;
  /** Logo URL */
  logo?: string;
  /** 深色模式 Logo URL */
  logoDark?: string;
  /** Favicon URL */
  favicon?: string;
  /** 主题色 */
  primaryColor?: string;
  /** 版权信息 */
  copyright?: string;
  /** ICP 备案号 */
  icp?: string;
}

/** 验证码配置 */
export interface CaptchaConfig {
  /** 是否启用验证码 */
  enabled: boolean;
  /** 验证码类型: image | slider | click */
  type: string;
  /** 难度等级: easy | medium | hard */
  difficulty: string;
  /** 失败多少次后显示验证码 */
  failedThreshold: number;
  /** 验证码提供方标识（后端驱动类型） */
  provider?: string;
}

/** 登录配置 */
export interface LoginConfig {
  /** 验证码配置 */
  captcha: CaptchaConfig;
  /** 允许的登录方式 */
  allowedMethods: string[];
  /** 最大尝试次数 */
  maxAttempts?: number;
  /** 锁定时间（分钟） */
  lockoutMinutes?: number;
}

/** 密码策略 */
export interface PasswordPolicy {
  minLength?: number;
  complexity?: string;
  expiryDays?: number;
}

/** 会话策略 */
export interface SessionPolicy {
  timeoutMinutes?: number;
  maxDevices?: number;
}

/** 安全配置 */
export interface SecurityConfig {
  password: PasswordPolicy;
  session: SessionPolicy;
}

/** 维护配置 */
export interface MaintenanceConfig {
  enabled: boolean;
  message?: string;
}

/** 域名配置 */
export interface DomainConfig {
  suffix: string;
  verificationPrefix: string;
}

/** 平台公开配置 */
export interface PlatformPublicConfig {
  /** 品牌配置 */
  brand: BrandConfig;
  /** 登录配置 */
  login: LoginConfig;
  /** 安全配置 */
  security: SecurityConfig;
  /** 维护配置 */
  maintenance: MaintenanceConfig;
  /** 域名配置 */
  domain: DomainConfig;
}

/** 企业公开配置 */
export interface TenantPublicConfig {
  /** 企业 ID */
  tenantId: number;
  /** 企业编码 */
  tenantCode: string;
  /** 企业名称 */
  tenantName: string;
  /** 品牌配置 */
  brand: BrandConfig;
  /** 登录配置 */
  login: LoginConfig;
  /** 安全配置 */
  security: SecurityConfig;
  /** 维护配置 */
  maintenance: MaintenanceConfig;
  /** 域名配置 */
  domain: DomainConfig;
  /** 功能开关 */
  features?: Record<string, boolean>;
}

// ============================================================
// 后端原始类型 (snake_case)
// ============================================================

interface PlatformPublicConfigRaw {
  // Brand
  site_name?: string;
  site_description?: string;
  site_logo?: string;
  site_favicon?: string;
  site_copyright?: string;
  site_icp?: string;
  primary_color?: string;
  logo_dark?: string;

  // Domain
  tenant_domain_suffix?: string;
  domain_verification_prefix?: string;

  // Maintenance
  maintenance_mode?: boolean;
  maintenance_message?: string;

  // Login / Captcha
  login_captcha_enabled?: boolean;
  captcha_type?: string;
  captcha_difficulty?: string;
  captcha_enable_threshold_admin?: number;
  captcha_provider?: string;
  login_max_attempts?: number;
  login_lockout_minutes?: number;
  allowed_methods?: string[];

  // Password
  password_min_length?: number;
  password_complexity?: string;
  password_expiry_days?: number;

  // Session
  session_timeout_minutes?: number;
  session_max_devices?: number;
}

interface TenantPublicConfigRaw {
  tenant_id: number;
  tenant_code: string;
  tenant_name: string;

  // Brand (backend returns these field names from TenantPublicConfig schema)
  logo_url?: string;
  favicon_url?: string;
  theme_color?: string;
  login_bg?: string;
  primary_color?: string;
  accent_color?: string;
  login_title?: string;
  login_subtitle?: string;
  footer_copyright?: string;

  // Domain
  subdomain?: string;
  subdomain_url?: string;

  // Maintenance (from platform fallback)
  maintenance_mode?: boolean;
  maintenance_message?: string;

  // Login / Captcha
  captcha_enabled?: boolean;
  captcha_provider?: string;
  captcha_difficulty?: string;
  captcha_enable_threshold?: number;
  login_methods?: string[];
  login_max_attempts?: number;
  login_lockout_minutes?: number;

  // Password
  password_min_length?: number;
  password_complexity?: string;

  // Session
  session_timeout?: number;

  // Features
  allow_registration?: boolean;
  registration_approval?: boolean;
  allow_profile_edit?: boolean;
  email_notification?: boolean;
  sms_notification?: boolean;
  api_access?: boolean;
  file_upload?: boolean;

  // Storage
  storage?: {
    allowed_extensions?: string;
    base_url?: string;
    chunk_size_mb?: number;
    driver?: string;
    max_file_size_mb?: number;
  };
}

// ============================================================
// 转换函数
// ============================================================

function transformPlatformConfig(
  raw: PlatformPublicConfigRaw,
): PlatformPublicConfig {
  return {
    brand: {
      siteName: raw.site_name,
      siteDescription: raw.site_description,
      logo: attachmentIdToUrl(raw.site_logo),
      logoDark: attachmentIdToUrl(raw.logo_dark),
      favicon: attachmentIdToUrl(raw.site_favicon),
      primaryColor: raw.primary_color,
      copyright: raw.site_copyright,
      icp: raw.site_icp,
    },
    login: {
      captcha: {
        enabled: raw.login_captcha_enabled ?? false,
        type: raw.captcha_type ?? 'image',
        difficulty: raw.captcha_difficulty ?? 'medium',
        failedThreshold: raw.captcha_enable_threshold_admin ?? 0,
        provider: raw.captcha_provider ?? 'image',
      },
      allowedMethods: raw.allowed_methods ?? [],
      maxAttempts: raw.login_max_attempts,
      lockoutMinutes: raw.login_lockout_minutes,
    },
    security: {
      password: {
        minLength: raw.password_min_length,
        complexity: raw.password_complexity,
        expiryDays: raw.password_expiry_days,
      },
      session: {
        timeoutMinutes: raw.session_timeout_minutes,
        maxDevices: raw.session_max_devices,
      },
    },
    maintenance: {
      enabled: raw.maintenance_mode ?? false,
      message: raw.maintenance_message,
    },
    domain: {
      suffix: raw.tenant_domain_suffix ?? '',
      verificationPrefix: raw.domain_verification_prefix ?? '',
    },
  };
}

function transformTenantConfig(raw: TenantPublicConfigRaw): TenantPublicConfig {
  return {
    tenantId: raw.tenant_id,
    tenantCode: raw.tenant_code,
    tenantName: raw.tenant_name,
    brand: {
      siteName: raw.login_title || raw.tenant_name,
      siteDescription: raw.login_subtitle,
      logo: attachmentIdToUrl(raw.logo_url),
      favicon: attachmentIdToUrl(raw.favicon_url),
      primaryColor: raw.primary_color,
      copyright: raw.footer_copyright,
    },
    login: {
      captcha: {
        enabled: raw.captcha_enabled ?? false,
        type: raw.captcha_provider ?? 'image',
        difficulty: raw.captcha_difficulty ?? 'medium',
        failedThreshold: raw.captcha_enable_threshold ?? 0,
        provider: raw.captcha_provider ?? 'image',
      },
      allowedMethods: raw.login_methods ?? ['password'],
      maxAttempts: raw.login_max_attempts,
      lockoutMinutes: raw.login_lockout_minutes,
    },
    security: {
      password: {
        minLength: raw.password_min_length,
        complexity: raw.password_complexity,
      },
      session: {
        timeoutMinutes: raw.session_timeout,
      },
    },
    maintenance: {
      enabled: raw.maintenance_mode ?? false,
      message: raw.maintenance_message,
    },
    domain: {
      suffix: '',
      verificationPrefix: '',
    },
    features: {
      ...(raw.allow_registration == null ? {} : { allow_registration: raw.allow_registration }),
      ...(raw.api_access == null ? {} : { api_access: raw.api_access }),
      ...(raw.file_upload == null ? {} : { file_upload: raw.file_upload }),
    },
  };
}

// ============================================================
// API 函数
// ============================================================

/** HTTP 响应包装类型 */
interface HttpResponse<T> {
  code: number;
  data: T;
  message: string;
}

/**
 * 获取平台公开配置
 * GET /api/public/platform/config
 * 无需认证
 */
export async function getPlatformPublicConfigApi(): Promise<PlatformPublicConfig> {
  // baseRequestClient 无拦截器，返回原始 AxiosResponse
  // AxiosResponse.data = HttpResponse { code, message, data }
  const response = await baseRequestClient.get<
    HttpResponse<PlatformPublicConfigRaw>
  >('/api/public/platform/config');

  // response 是 AxiosResponse，response.data 是 HttpResponse
  const httpResponse = response as unknown as {
    data: HttpResponse<PlatformPublicConfigRaw>;
  };
  const responseData = httpResponse.data;

  if (responseData.code !== 0) {
    throw new Error(responseData.message || 'Failed to get platform config');
  }

  return transformPlatformConfig(responseData.data);
}

/**
 * 获取企业公开配置
 * GET /api/public/tenant/config
 * 无需认证，根据域名自动识别企业
 * 开发环境支持通过 tenantCode 参数指定企业
 */
export async function getTenantPublicConfigApi(
  tenantCode?: string,
): Promise<TenantPublicConfig> {
  const params: Record<string, string> = {};
  if (tenantCode) {
    params.tenant_code = tenantCode;
  }

  const response = await baseRequestClient.get<
    HttpResponse<TenantPublicConfigRaw>
  >('/api/public/tenant/config', { params });

  // response 是 AxiosResponse，response.data 是 HttpResponse
  const httpResponse = response as unknown as {
    data: HttpResponse<TenantPublicConfigRaw>;
  };
  const responseData = httpResponse.data;

  if (responseData.code !== 0) {
    throw new Error(responseData.message || 'Failed to get tenant config');
  }

  return transformTenantConfig(responseData.data);
}

/**
 * 系统智能体绑定 API（共享）
 *
 * 提供 resolve 函数，根据 feature_code 获取绑定的 agent_id。
 * 自动根据当前用户 API 前缀（admin/tenant）选择对应端点。
 */

import { requestClient } from '#/utils/request';

/** Resolve 响应 */
export interface AgentAssignmentResolveResult {
  feature_code: string;
  agent_id: null | number;
  agent_name: null | string;
  config: null | Record<string, unknown>;
  is_active: boolean;
  is_override?: boolean;
}

/** 绑定列表项 */
export interface AgentAssignmentItem {
  id: number;
  feature_code: string;
  feature_name: string;
  description: null | string;
  agent_id: null | number;
  agent_name: null | string;
  agent_avatar: null | string;
  is_active: boolean;
  is_override: boolean;
  config?: null | Record<string, unknown>;
  created_at?: string;
  updated_at?: string;
  global_agent_id?: null | number;
  global_agent_name?: null | string;
  display_name?: Record<string, string>;
  description_i18n?: Record<string, string>;
}

/**
 * Resolve 智能体绑定
 *
 * @param apiPrefix - '/admin' 或 '/tenant'
 * @param featureCode - 功能代码，如 'general_chat'
 */
export async function resolveAgentAssignmentApi(
  apiPrefix: string,
  featureCode: string,
): Promise<AgentAssignmentResolveResult> {
  return requestClient.get<AgentAssignmentResolveResult>(
    `${apiPrefix}/ai/agent-assignments/resolve/${featureCode}`,
  );
}

/**
 * 获取智能体绑定列表
 *
 * @param apiPrefix - '/admin' 或 '/tenant'
 */
export async function getAgentAssignmentListApi(
  apiPrefix: string,
): Promise<{ items: AgentAssignmentItem[]; total: number }> {
  return requestClient.get<{ items: AgentAssignmentItem[]; total: number }>(
    `${apiPrefix}/ai/agent-assignments`,
  );
}

/** 已发布智能体选项 */
export interface PublishedAgentOption {
  id: number;
  name: string;
  status: string;
}

/**
 * 获取已发布智能体列表（用于 Select 下拉）
 *
 * @param apiPrefix - '/admin' 或 '/tenant'
 */
export async function getPublishedAgentsApi(
  apiPrefix: string,
): Promise<{ items: PublishedAgentOption[] }> {
  return requestClient.get<{ items: PublishedAgentOption[] }>(
    `${apiPrefix}/ai/agents`,
    { params: { 'filter[status][eq]': 'published', 'page[size]': 100 } },
  );
}

/**
 * 更新智能体绑定
 *
 * @param apiPrefix - '/admin' 或 '/tenant'
 * @param featureCode - 功能代码
 * @param data - 更新数据（agent_id 和/或 is_active）
 */
export async function updateAgentAssignmentApi(
  apiPrefix: string,
  featureCode: string,
  data: { agent_id?: null | number; is_active?: boolean },
): Promise<unknown> {
  return requestClient.put(
    `${apiPrefix}/ai/agent-assignments/${featureCode}`,
    data,
  );
}

/**
 * 删除企业覆盖（恢复全局默认）
 *
 * @param apiPrefix - '/admin' 或 '/tenant'
 * @param featureCode - 功能代码
 */
export async function deleteAgentAssignmentApi(
  apiPrefix: string,
  featureCode: string,
): Promise<unknown> {
  return requestClient.delete(
    `${apiPrefix}/ai/agent-assignments/${featureCode}`,
  );
}

/**
 * AI Chat Composable
 *
 * Encapsulates all AI chat business logic: agent loading, conversation management,
 * SSE streaming, file uploads, tool calls, consent handling.
 * Used by both the full-page chat and the global drawer chat.
 */
import type { Ref } from 'vue';

import type {
  AgentItem,
  ChatAttachment,
  ChatMessage,
  ConversationItem,
  ToolCallEvent,
} from './types';

import { computed, nextTick, ref, unref } from 'vue';

import { message } from 'ant-design-vue';

import {
  clearChatConversationMemoryApi,
  deleteChatConversationApi,
  getChatAgentsApi,
  getChatConversationMessagesApi,
  getChatConversationsApi,
  sendChatStreamApi,
  uploadChatFileApi,
} from '#/api/shared/ai-chat';
import { useFileUpload } from '#/composables/use-file-upload';
import { CHAT_ACCEPT_ATTRIBUTE } from '#/constants/upload';
import { $t } from '#/locales';
import { addConsent, getConsentedActions } from '#/utils/ai-consent';

export interface UseAIChatOptions {
  /** API prefix: '/admin' or '/tenant' */
  apiPrefix: Ref<string> | string;
  /** Upload endpoint */
  uploadUrl: Ref<string> | string;
  /** Initial agent ID to auto-select after loading agents */
  initialAgentId?: number | Ref<number | undefined>;
  /** Initial conversation ID to auto-load after agent is selected */
  initialConversationId?: number | Ref<number | undefined>;
  /** Callback when a tool call completes successfully */
  onToolCall?: (toolName: string, output: string) => void;
  /** Callback when streaming completes (used for unread badge) */
  onStreamComplete?: () => void;
}

export function useAIChat(options: UseAIChatOptions) {
  const { validateChatFile, revokePreviewUrls } = useFileUpload();

  // ============ Agents ============

  const agents = ref<AgentItem[]>([]);
  const agentsLoading = ref(false);
  const selectedAgentId = ref<null | number>(null);

  const selectedAgent = computed(
    () => agents.value.find((a) => a.id === selectedAgentId.value) ?? null,
  );

  /**
   * Load agents list and auto-select one.
   * @param overrideAgentId - If provided, takes priority over options.initialAgentId
   */
  async function loadAgents(overrideAgentId?: number) {
    agentsLoading.value = true;
    try {
      const prefix = unref(options.apiPrefix) as string;
      const res = await getChatAgentsApi<AgentItem>(prefix);
      agents.value = res.items;
      if (res.items.length > 0 && !selectedAgentId.value) {
        const initId = overrideAgentId ?? unref(options.initialAgentId);
        selectedAgentId.value =
          initId && res.items.some((a) => a.id === initId)
            ? initId
            : res.items[0]!.id;
      }
    } catch {
      // handled by interceptor
    } finally {
      agentsLoading.value = false;
    }
  }

  function selectAgent(agentId: number) {
    if (selectedAgentId.value === agentId) return;
    selectedAgentId.value = agentId;
    conversationsRequestSeq += 1;
    messagesRequestSeq += 1;
    activeConversationId.value = null;
    chatMessages.value = [];
    clearPendingAttachments();
  }

  // ============ Conversations ============

  const conversations = ref<ConversationItem[]>([]);
  const conversationsLoading = ref(false);
  const activeConversationId = ref<null | number>(null);
  const clearingMemory = ref(false);

  /** 请求序号防护：避免旧异步响应覆盖最新状态 */
  let conversationsRequestSeq = 0;
  let messagesRequestSeq = 0;

  async function loadConversations() {
    if (!selectedAgentId.value) return;
    const currentAgentId = selectedAgentId.value;
    const reqSeq = ++conversationsRequestSeq;
    conversationsLoading.value = true;
    try {
      const prefix = unref(options.apiPrefix) as string;
      const res = await getChatConversationsApi<ConversationItem>(
        prefix,
        currentAgentId,
      );
      if (
        reqSeq !== conversationsRequestSeq ||
        selectedAgentId.value !== currentAgentId
      ) {
        return;
      }
      conversations.value = res.items;

      // Auto-load initial conversation (only once)
      const initConvId = unref(options.initialConversationId);
      if (
        initConvId &&
        !_initialConvRestored &&
        res.items.some((c) => c.id === initConvId)
      ) {
        _initialConvRestored = true;
        await loadConversationMessages(initConvId);
      }
    } catch {
      // handled by interceptor
    } finally {
      if (reqSeq === conversationsRequestSeq) {
        conversationsLoading.value = false;
      }
    }
  }

  function startNewConversation() {
    messagesRequestSeq += 1;
    activeConversationId.value = null;
    chatMessages.value = [];
  }

  async function deleteConversation(convId: number) {
    try {
      const prefix = unref(options.apiPrefix) as string;
      await deleteChatConversationApi(prefix, selectedAgentId.value!, convId);
      if (activeConversationId.value === convId) {
        messagesRequestSeq += 1;
        activeConversationId.value = null;
        chatMessages.value = [];
      }
      await loadConversations();
    } catch {
      // handled by interceptor
    }
  }

  async function loadConversationMessages(convId: number) {
    const currentAgentId = selectedAgentId.value;
    if (!currentAgentId) return;
    const reqSeq = ++messagesRequestSeq;
    activeConversationId.value = convId;
    try {
      const prefix = unref(options.apiPrefix) as string;
      const res = await getChatConversationMessagesApi(
        prefix,
        currentAgentId,
        convId,
      );
      if (
        reqSeq !== messagesRequestSeq ||
        selectedAgentId.value !== currentAgentId ||
        activeConversationId.value !== convId
      ) {
        return;
      }

      chatMessages.value = mergeMessagesForDisplay(res.message_list ?? []);
      scrollToBottom(true);
    } catch {
      // handled by interceptor
    }
  }

  async function clearConversationMemory(): Promise<boolean> {
    if (
      !selectedAgentId.value ||
      !activeConversationId.value ||
      clearingMemory.value
    ) {
      return false;
    }
    clearingMemory.value = true;
    try {
      const prefix = unref(options.apiPrefix) as string;
      await clearChatConversationMemoryApi(
        prefix,
        selectedAgentId.value,
        activeConversationId.value,
      );
      return true;
    } catch {
      return false;
    } finally {
      clearingMemory.value = false;
    }
  }

  /**
   * Merge raw DB messages into display ChatMessages.
   *
   * During streaming, all tool call rounds are accumulated into a single
   * assistant ChatMessage. But the DB stores each round as separate messages:
   *   assistant (tool_calls) → tool → assistant (tool_calls) → tool → ... → assistant (final content)
   *
   * This function groups consecutive non-user messages between user messages
   * into a single ChatMessage with toolCalls reconstructed.
   */
  function mergeMessagesForDisplay(
    rawMessages: Array<{
      content: null | string;
      metadata?: null | { attachments?: ChatAttachment[] };
      role: string;
      tool_call_id?: null | string;
      tool_calls?: Array<{
        function?: { arguments?: string; name?: string };
        id?: string;
      }> | null;
      tool_name?: null | string;
    }>,
  ): ChatMessage[] {
    // Filter out system messages
    const filtered = rawMessages.filter((m) => m.role !== 'system');
    if (filtered.length === 0) return [];

    const result: ChatMessage[] = [];

    // Collect tool responses keyed by tool_call_id for quick lookup
    const toolResponseMap = new Map<
      string,
      { content: string; error?: string; name?: string; success: boolean }
    >();
    for (const m of filtered) {
      if (m.role === 'tool' && m.tool_call_id) {
        const meta = (m.metadata ?? {}) as Record<string, unknown>;
        const toolSuccess = meta.tool_success !== false; // default true for legacy data
        toolResponseMap.set(m.tool_call_id, {
          content: m.content ?? '',
          success: toolSuccess,
          error: (meta.tool_error as string) || undefined,
          name: m.tool_name ?? undefined,
        });
      }
    }

    // Group consecutive non-user messages into assistant turns
    let i = 0;
    while (i < filtered.length) {
      const msg = filtered[i]!;

      if (msg.role === 'user') {
        result.push({
          role: 'user',
          content: msg.content ?? '',
          attachments: msg.metadata?.attachments,
        });
        i++;
        continue;
      }

      // Collect all consecutive non-user messages as one assistant turn
      const toolCalls: ToolCallEvent[] = [];
      const contentParts: string[] = [];
      const startIdx = i;

      while (i < filtered.length && filtered[i]!.role !== 'user') {
        const cur = filtered[i]!;

        if (cur.role === 'assistant') {
          // Extract tool calls from this assistant message
          if (cur.tool_calls && cur.tool_calls.length > 0) {
            for (const tc of cur.tool_calls) {
              const tcId = tc.id ?? '';
              const funcName = tc.function?.name ?? 'unknown';
              let parsedArgs: Record<string, unknown> | undefined;
              try {
                parsedArgs = tc.function?.arguments
                  ? JSON.parse(tc.function.arguments)
                  : undefined;
              } catch {
                parsedArgs = tc.function?.arguments
                  ? { raw: tc.function.arguments }
                  : undefined;
              }

              // Match with tool response (use metadata.tool_success for status)
              const response = tcId ? toolResponseMap.get(tcId) : undefined;

              toolCalls.push({
                name: funcName,
                status: response
                  ? response.success
                    ? 'success'
                    : 'error'
                  : 'error',
                arguments: parsedArgs,
                output: response?.success ? response.content : undefined,
                error:
                  response && !response.success
                    ? response.error || response.content
                    : undefined,
              });
            }
          }

          // Accumulate content from all assistant messages in this turn
          // (matches streaming behavior where all deltas are concatenated)
          if (cur.content && cur.content.trim()) {
            contentParts.push(cur.content);
          }
        }
        // tool messages are already handled via toolResponseMap
        i++;
      }

      // Only add if we actually processed something
      if (i > startIdx) {
        result.push({
          role: 'assistant',
          content: contentParts.join('\n\n'),
          toolCalls: toolCalls.length > 0 ? toolCalls : undefined,
        });
      }
    }

    return result;
  }

  // ============ Chat Messages ============

  /** Guard: only restore initialConversationId once */
  let _initialConvRestored = false;

  const chatMessages = ref<ChatMessage[]>([]);
  const inputMessage = ref('');
  const selectedKBIds = ref<number[]>([]);
  const sending = ref(false);
  const streaming = ref(false);
  const messagesContainer = ref<HTMLElement | null>(null);

  let streamAbortController: AbortController | null = null;

  /** Whether user has manually scrolled up during streaming */
  let userScrolledUp = false;

  /**
   * Smart scroll: only auto-scroll to bottom if user hasn't scrolled up.
   * @param force - if true, always scroll regardless of user position
   */
  function scrollToBottom(force = false) {
    nextTick(() => {
      const el = messagesContainer.value;
      if (!el) return;
      if (force || !userScrolledUp) {
        el.scrollTop = el.scrollHeight;
      }
    });
  }

  /** Check if the user is near the bottom of the scroll container */
  function isNearBottom(): boolean {
    const el = messagesContainer.value;
    if (!el) return true;
    const threshold = 80;
    return el.scrollHeight - el.scrollTop - el.clientHeight < threshold;
  }

  /** Handle scroll events to detect manual user scroll-up */
  function handleMessagesScroll() {
    if (!streaming.value) return;
    userScrolledUp = !isNearBottom();
  }

  async function copyMessage(content: string) {
    try {
      await navigator.clipboard.writeText(content);
    } catch {
      // fallback silently
    }
  }

  function handleInputKeyDown(e: KeyboardEvent) {
    if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) {
      e.preventDefault();
      sendMessage();
    }
  }

  // ============ Model Capabilities ============

  const supportsVision = computed(
    () => selectedAgent.value?.model_capabilities?.supports_vision ?? false,
  );

  const totalTokensUsed = computed(() =>
    chatMessages.value.reduce((sum, m) => sum + (m.tokenUsage || 0), 0),
  );

  const imageParams = ref<{
    n: number;
    quality: string;
    size: string;
    style: string;
  }>({
    size: '1024x1024',
    quality: 'standard',
    style: 'vivid',
    n: 1,
  });

  const maxImageCount = computed(
    () => selectedAgent.value?.model_capabilities?.max_image_count ?? 5,
  );

  const maxImageSizeMb = computed(
    () => selectedAgent.value?.model_capabilities?.max_image_size_mb ?? 10,
  );

  /**
   * Validate a file before upload (images + non-images).
   * Uses the unified useFileUpload composable.
   */
  function validateUpload(file: File): boolean {
    const currentImageCount = pendingAttachments.value.filter(
      (a) => a.type === 'image',
    ).length;
    const result = validateChatFile(file, {
      supportsVision: supportsVision.value,
      maxImageCount: maxImageCount.value,
      currentImageCount,
      maxImageSizeMb: maxImageSizeMb.value,
    });
    return result.valid;
  }

  // ============ File Uploads ============

  const pendingAttachments = ref<ChatAttachment[]>([]);
  const uploading = ref(false);
  const fileInput = ref<HTMLInputElement | null>(null);
  /** Pre-built accept attribute for file input */
  const chatAcceptAttribute = CHAT_ACCEPT_ATTRIBUTE;

  /**
   * Compress an image file using Canvas API.
   * Returns the original file if compression is not possible or not needed.
   */
  async function compressImage(
    file: File,
    maxDimension = 2048,
    quality = 0.85,
  ): Promise<File> {
    return new Promise((resolve) => {
      const img = new Image();
      img.addEventListener('load', () => {
        URL.revokeObjectURL(img.src);
        let { width, height } = img;
        if (
          width <= maxDimension &&
          height <= maxDimension &&
          file.size < 1024 * 1024
        ) {
          resolve(file);
          return;
        }
        if (width > maxDimension || height > maxDimension) {
          const ratio = Math.min(maxDimension / width, maxDimension / height);
          width = Math.round(width * ratio);
          height = Math.round(height * ratio);
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (!ctx) {
          resolve(file);
          return;
        }
        ctx.drawImage(img, 0, 0, width, height);
        canvas.toBlob(
          (blob) => {
            if (!blob || blob.size >= file.size) {
              resolve(file);
              return;
            }
            resolve(
              new File([blob], file.name, {
                type: 'image/jpeg',
                lastModified: Date.now(),
              }),
            );
          },
          'image/jpeg',
          quality,
        );
      });
      img.onerror = () => {
        URL.revokeObjectURL(img.src);
        resolve(file);
      };
      img.src = URL.createObjectURL(file);
    });
  }

  /**
   * Determine extra upload form data based on API prefix.
   * Admin endpoint needs tenant_id=0 for platform attachments.
   */
  function getUploadExtraData(): Record<string, string> | undefined {
    const prefix = unref(options.apiPrefix) as string;
    if (prefix.includes('/admin')) {
      return { tenant_id: '0' };
    }
    return undefined;
  }

  async function uploadFile(file: File): Promise<ChatAttachment | null> {
    uploading.value = true;
    try {
      const isImage = file.type.startsWith('image/');
      const fileToUpload = isImage ? await compressImage(file) : file;
      const data = await uploadChatFileApi(
        unref(options.uploadUrl) as string,
        fileToUpload,
        getUploadExtraData(),
      );
      return {
        type: isImage ? 'image' : 'file',
        url: data.url,
        name: file.name,
        mime_type: fileToUpload.type,
        preview: isImage ? URL.createObjectURL(fileToUpload) : undefined,
      };
    } catch (error: unknown) {
      const errorMsg =
        error instanceof Error
          ? error.message
          : $t('common.uploadValidation.uploadFailed');
      message.error(errorMsg);
      return null;
    } finally {
      uploading.value = false;
    }
  }

  async function handleFileSelect(e: Event) {
    const input = e.target as HTMLInputElement;
    if (!input.files?.length) return;
    for (const file of input.files) {
      if (!validateUpload(file)) continue;
      const att = await uploadFile(file);
      if (att) pendingAttachments.value.push(att);
    }
    input.value = '';
  }

  async function handlePaste(e: ClipboardEvent) {
    const items = e.clipboardData?.items;
    if (!items) return;

    const imageFiles: File[] = [];
    for (const item of items) {
      if (item.type.startsWith('image/')) {
        const file = item.getAsFile();
        if (file) imageFiles.push(file);
      }
    }
    if (imageFiles.length === 0) return;

    e.preventDefault();

    for (const file of imageFiles) {
      if (!validateUpload(file)) continue;
      const att = await uploadFile(file);
      if (att) pendingAttachments.value.push(att);
    }
  }

  function handleDragOver(e: DragEvent) {
    e.preventDefault();
  }

  async function handleDrop(e: DragEvent) {
    e.preventDefault();
    const files = e.dataTransfer?.files;
    if (!files?.length) return;
    for (const file of files) {
      if (!validateUpload(file)) continue;
      const att = await uploadFile(file);
      if (att) pendingAttachments.value.push(att);
    }
  }

  function removePendingAttachment(idx: number) {
    const att = pendingAttachments.value[idx];
    if (att?.preview) URL.revokeObjectURL(att.preview);
    pendingAttachments.value.splice(idx, 1);
  }

  /** Clear pending attachments and revoke all preview URLs */
  function clearPendingAttachments() {
    revokePreviewUrls(pendingAttachments.value);
    pendingAttachments.value = [];
  }

  // ============ SSE Streaming ============

  function parseSSEEvents(
    rawChunk: string,
    buffer: { value: string },
    handler: (data: string) => void,
  ) {
    buffer.value += rawChunk;
    const lines = buffer.value.split('\n');
    buffer.value = lines.pop() ?? '';
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('data: ')) {
        handler(trimmed.slice(6));
      }
    }
  }

  async function sendMessage(opts?: { silent?: boolean }) {
    const silent = opts?.silent ?? false;
    const hasText = inputMessage.value.trim().length > 0;
    const hasAttachments = pendingAttachments.value.length > 0;
    if (
      (!hasText && !hasAttachments) ||
      !selectedAgentId.value ||
      sending.value
    )
      return;

    const userMsg = inputMessage.value.trim();
    const msgAttachments = [...pendingAttachments.value];

    if (!silent) {
      chatMessages.value.push({
        role: 'user',
        content: userMsg,
        attachments: msgAttachments.length > 0 ? msgAttachments : undefined,
      });
    }
    chatMessages.value.push({
      role: 'assistant',
      content: '',
      streaming: true,
    });
    userScrolledUp = false;
    scrollToBottom(true);

    inputMessage.value = '';
    clearPendingAttachments();
    await nextTick();

    sending.value = true;
    streaming.value = true;
    const sseBuffer = { value: '' };
    streamAbortController = new AbortController();
    const assistantIdx = chatMessages.value.length - 1;

    const apiAttachments =
      msgAttachments.length > 0
        ? msgAttachments.map(({ type, url, name, mime_type }) => ({
            type,
            url,
            name,
            mime_type,
          }))
        : undefined;

    function finalizeMessage() {
      const msg = chatMessages.value[assistantIdx];
      if (msg) {
        msg.streaming = false;
        if (msg.toolCalls) {
          for (const tc of msg.toolCalls) {
            if (tc.status === 'running') {
              tc.status = 'error';
            }
          }
        }
      }
    }

    try {
      const prefix = unref(options.apiPrefix) as string;
      await sendChatStreamApi(
        prefix,
        selectedAgentId.value!,
        {
          message: userMsg || ' ',
          conversation_id: activeConversationId.value,
          ...(selectedKBIds.value.length > 0
            ? { knowledge_base_ids: selectedKBIds.value }
            : {}),
          consented_actions: getConsentedActions(),
          ...(apiAttachments ? { attachments: apiAttachments } : {}),
          ...(imageParams.value.size !== '1024x1024' ||
          imageParams.value.quality !== 'standard' ||
          imageParams.value.style !== 'vivid' ||
          imageParams.value.n !== 1
            ? { image_params: imageParams.value }
            : {}),
        },
        {
          abortController: streamAbortController,
          onMessage(rawChunk: string) {
            parseSSEEvents(rawChunk, sseBuffer, (data) => {
              if (data === '[DONE]') return;
              try {
                const event = JSON.parse(data);
                const msg = chatMessages.value[assistantIdx];
                if (!msg) return;

                switch (event.event) {
                  case 'optimizing_tools': {
                    msg.optimizingTools = {
                      total: event.total || 0,
                      selected: event.selected || 0,
                    };
                    scrollToBottom();

                    break;
                  }
                  case 'thinking': {
                    // frontend already shows loading via streaming + !content

                    break;
                  }
                  case 'tool_call': {
                    if (!msg.toolCalls) msg.toolCalls = [];
                    // Find matching running tool and update it
                    const existing = msg.toolCalls.findLast(
                      (tc) => tc.name === event.name && tc.status === 'running',
                    );
                    if (existing) {
                      existing.status = event.success ? 'success' : 'error';
                      existing.durationMs = event.duration_ms;
                      existing.output = event.output;
                      existing.error = event.error;
                      if (event.skill_name)
                        existing.skillName = event.skill_name;
                      if (event.skill_type)
                        existing.skillType = event.skill_type;
                      if (event.display_name)
                        existing.displayName = event.display_name;
                      if (event.summary) existing.summary = event.summary;
                      if (event.result_link)
                        existing.resultLink = event.result_link;
                    } else {
                      msg.toolCalls.push({
                        name: event.name,
                        status: event.success ? 'success' : 'error',
                        durationMs: event.duration_ms,
                        output: event.output,
                        error: event.error,
                        skillName: event.skill_name || undefined,
                        skillType: event.skill_type || undefined,
                        displayName: event.display_name || undefined,
                        summary: event.summary || undefined,
                        resultLink: event.result_link || undefined,
                      });
                    }
                    // Dispatch successful tool calls to external handler
                    if (event.success && options.onToolCall) {
                      options.onToolCall(event.name, event.output ?? '');
                    }
                    scrollToBottom();

                    break;
                  }
                  case 'tool_start': {
                    if (!msg.toolCalls) msg.toolCalls = [];
                    msg.toolCalls.push({
                      name: event.name,
                      status: 'running',
                      arguments: event.arguments,
                      skillName: event.skill_name || undefined,
                      skillType: event.skill_type || undefined,
                    });
                    scrollToBottom();

                    break;
                  }
                  default: {
                    if (
                      event.event === 'authorization_required' &&
                      event.consent_key
                    ) {
                      addConsent(event.consent_key);
                    } else if (event.event === 'confirmation_request') {
                      msg.pendingConfirmation = {
                        action: event.action || '',
                        table: event.table || '',
                        preview: event.preview,
                      };
                    } else if (event.event === 'tool_consent_request') {
                      msg.pendingConsent = {
                        toolName: event.name || '',
                        arguments: event.arguments,
                        skillName: event.skill_name || undefined,
                        skillType: event.skill_type || undefined,
                      };
                      scrollToBottom();
                    } else if (
                      event.event === 'action_buttons' &&
                      event.buttons
                    ) {
                      msg.actionButtons = event.buttons;
                      scrollToBottom();
                    } else if (event.event === 'image_result' && event.url) {
                      if (!msg.imageResults) msg.imageResults = [];
                      msg.imageResults.push({
                        url: event.url,
                        isBase64: event.is_base64 || false,
                        revisedPrompt: event.revised_prompt || undefined,
                      });
                      scrollToBottom();
                    } else if (event.event === 'rag_sources' && event.sources) {
                      msg.ragSources = event.sources;
                    } else if (event.event === 'message' && event.delta) {
                      msg.content += event.delta;
                      scrollToBottom();
                    } else if (event.event === 'done') {
                      msg.tokenUsage = event.total_tokens || 0;
                      msg.durationMs = event.duration_ms || 0;
                      if (event.conversation_id) {
                        activeConversationId.value = event.conversation_id;
                      }
                      if (options.onStreamComplete) {
                        options.onStreamComplete();
                      }
                    } else if (event.error) {
                      msg.content = `\u26A0\uFE0F ${
                        event.message || $t('common.requestFailed')
                      }`;
                    }
                  }
                }
              } catch {
                // ignore unparseable lines
              }
            });
          },
          onEnd() {
            loadConversations();
          },
          onError(error: Error) {
            if (error.name === 'AbortError') return;
            const msg = chatMessages.value[assistantIdx];
            if (msg && !msg.content) {
              msg.content = `\u26A0\uFE0F ${$t('common.requestFailed')}`;
            }
            finalizeMessage();
          },
        },
      );
    } catch {
      // postSSE handles errors internally via onError
    } finally {
      sending.value = false;
      streaming.value = false;
      streamAbortController = null;
      userScrolledUp = false;
      finalizeMessage();
    }
  }

  function confirmAction(msgIndex: number) {
    const msg = chatMessages.value[msgIndex];
    if (!msg?.pendingConfirmation || msg.pendingConfirmation.resolved) return;
    msg.pendingConfirmation.resolved = true;
    inputMessage.value = $t('common.globalAiChat.confirmExecute');
    sendMessage({ silent: true });
  }

  function rejectAction(msgIndex: number) {
    const msg = chatMessages.value[msgIndex];
    if (!msg?.pendingConfirmation || msg.pendingConfirmation.resolved) return;
    msg.pendingConfirmation.resolved = true;
    inputMessage.value = $t('common.globalAiChat.rejectExecute');
    sendMessage({ silent: true });
  }

  function confirmConsent(msgIndex: number) {
    const msg = chatMessages.value[msgIndex];
    if (!msg?.pendingConsent || msg.pendingConsent.resolved) return;
    msg.pendingConsent.resolved = true;
    inputMessage.value = $t('common.globalAiChat.confirmExecute');
    sendMessage({ silent: true });
  }

  function rejectConsent(msgIndex: number) {
    const msg = chatMessages.value[msgIndex];
    if (!msg?.pendingConsent || msg.pendingConsent.resolved) return;
    msg.pendingConsent.resolved = true;
    inputMessage.value = $t('common.globalAiChat.rejectExecute');
    sendMessage({ silent: true });
  }

  function clickActionButton(msgIndex: number, value: string) {
    const msg = chatMessages.value[msgIndex];
    if (!msg || msg.actionButtonsUsed) return;
    msg.actionButtonsUsed = true;
    inputMessage.value = value;
    sendMessage();
  }

  function editAndResend(msgIndex: number) {
    if (sending.value || streaming.value) return;
    const msg = chatMessages.value[msgIndex];
    if (!msg || msg.role !== 'user') return;

    // Fill input with the user message content
    inputMessage.value = msg.content;

    // Remove this message and all subsequent messages
    chatMessages.value.splice(msgIndex);
  }

  function exportAsMarkdown() {
    if (chatMessages.value.length === 0) return;
    const agentName = selectedAgent.value?.name || 'AI';
    const lines: string[] = [
      `# ${agentName} - ${$t('common.globalAiChat.history')}`,
      '',
    ];
    for (const msg of chatMessages.value) {
      const role = msg.role === 'user' ? '**User**' : `**${agentName}**`;
      lines.push(`### ${role}`, '');
      if (msg.content) lines.push(msg.content);
      if (msg.toolCalls?.length) {
        lines.push('');
        for (const tc of msg.toolCalls) {
          const duration = tc.durationMs
            ? ` (${(tc.durationMs / 1000).toFixed(1)}s)`
            : '';
          const skill = tc.skillName ? `${tc.skillName} › ` : '';
          lines.push(
            `> 🔧 ${skill}${tc.displayName || tc.name} — ${tc.status}${duration}`,
          );
          if (tc.arguments && Object.keys(tc.arguments).length > 0) {
            lines.push(`> **Args:** \`${JSON.stringify(tc.arguments)}\``);
          }
          if (tc.output) {
            lines.push(
              `> **Output:** ${tc.output.slice(0, 500)}${tc.output.length > 500 ? '...' : ''}`,
            );
          }
          if (tc.error) {
            lines.push(`> **Error:** ${tc.error}`);
          }
        }
      }
      lines.push('');
    }
    const blob = new Blob([lines.join('\n')], {
      type: 'text/markdown;charset=utf-8',
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `chat-${activeConversationId.value || 'new'}-${Date.now()}.md`;
    a.click();
    URL.revokeObjectURL(url);
  }

  function regenerateMessage(msgIndex: number) {
    if (sending.value || streaming.value) return;
    const msg = chatMessages.value[msgIndex];
    if (!msg || msg.role !== 'assistant') return;

    // Find the preceding user message
    let userMsgIndex = -1;
    for (let i = msgIndex - 1; i >= 0; i--) {
      if (chatMessages.value[i]?.role === 'user') {
        userMsgIndex = i;
        break;
      }
    }
    if (userMsgIndex < 0) return;

    const userContent = chatMessages.value[userMsgIndex]!.content;
    const userAttachments = chatMessages.value[userMsgIndex]!.attachments;

    // Remove the assistant message (and any messages after it)
    chatMessages.value.splice(msgIndex);

    // Re-send the user message
    inputMessage.value = userContent;
    if (userAttachments?.length) {
      pendingAttachments.value = [...userAttachments];
    }
    sendMessage({ silent: true });
  }

  function stopGeneration() {
    if (streamAbortController) {
      streamAbortController.abort();
      streamAbortController = null;
    }
    sending.value = false;
    streaming.value = false;
    userScrolledUp = false;
    const last = chatMessages.value.at(-1);
    if (last?.streaming) last.streaming = false;
  }

  function cleanup() {
    if (streamAbortController) {
      streamAbortController.abort();
    }
  }

  // ============ Helpers ============

  return {
    // Agents
    agents,
    agentsLoading,
    selectedAgentId,
    selectedAgent,
    loadAgents,
    selectAgent,

    // Conversations
    conversations,
    conversationsLoading,
    activeConversationId,
    loadConversations,
    startNewConversation,
    deleteConversation,
    clearConversationMemory,
    clearingMemory,
    loadConversationMessages,

    // Chat
    chatMessages,
    inputMessage,
    selectedKBIds,
    sending,
    streaming,
    messagesContainer,
    sendMessage,
    stopGeneration,
    scrollToBottom,
    handleMessagesScroll,
    copyMessage,
    handleInputKeyDown,
    confirmAction,
    rejectAction,
    confirmConsent,
    rejectConsent,
    clickActionButton,
    regenerateMessage,
    editAndResend,
    cleanup,

    // Model capabilities
    supportsVision,
    imageParams,
    exportAsMarkdown,
    totalTokensUsed,

    // Attachments
    pendingAttachments,
    uploading,
    fileInput,
    chatAcceptAttribute,
    uploadFile,
    handleFileSelect,
    handlePaste,
    handleDrop,
    handleDragOver,
    removePendingAttachment,
    clearPendingAttachments,
  };
}

/** * 配置项图片选择器 * * 配合 ConfigForm 使用，在系统配置中为
value_type='image' 的配置项提供图片选择功能。 * 通过 FilePicker
附件管理器弹窗选择图片，存储附件 ID（字符串）， * 显示时根据 ID 动态拼接图片处理
URL。 * * @example *
<ConfigImagePicker v-model="formModel[cfg.key]" />
*
<ConfigImagePicker v-model="value" accept="image/png,image/jpeg" />
*/
<script setup lang="ts">
import type { AttachmentInfo } from '#/types/attachment';

import { ref } from 'vue';

import { IconifyIcon } from '@vben/icons';

import { Button, Form, Image } from 'ant-design-vue';

import { FilePicker } from '#/components/business/file-picker';
import { $t } from '#/locales';
import { getProcessedImageUrl } from '#/utils/image';

withDefaults(
  defineProps<{
    /** 允许的文件类型，传给 FilePicker 的 accept（如 'image/*', 'image/png'） */
    accept?: string;
    /** 是否仅显示图片类型文件 */
    imageOnly?: boolean;
    /** 当前值：附件 ID（字符串形式），也兼容旧的 URL 格式 */
    modelValue?: string;
  }>(),
  {
    accept: 'image/*',
    imageOnly: true,
  },
);

const emit = defineEmits<{ (e: 'update:modelValue', v: string): void }>();

const filePickerRef = ref<InstanceType<typeof FilePicker>>();
const previewVisible = ref(false);

/**
 * 将存储的附件 ID 转换为缩略图 URL（用于列表/卡片预览）
 * 如果值是旧格式的完整 URL，直接返回
 */
function toDisplayUrl(val: string | undefined): string {
  if (!val) return '';
  const id = Number(val);
  if (Number.isFinite(id) && id > 0) {
    return getProcessedImageUrl(id, { preset: 'medium' });
  }
  // 兼容旧的 URL 格式
  return val;
}

/**
 * 将存储的附件 ID 转换为原图 URL（用于放大镜查看大图）
 * 不传 preset 参数，返回原始尺寸图片
 */
function toPreviewUrl(val: string | undefined): string {
  if (!val) return '';
  const id = Number(val);
  if (Number.isFinite(id) && id > 0) {
    return getProcessedImageUrl(id);
  }
  return val;
}

/** 打开附件管理器弹窗 */
function openPicker() {
  filePickerRef.value?.open();
}

/** 选择文件后，将附件 ID（字符串）通过 v-model 传出 */
function handleSelect(files: AttachmentInfo[]) {
  if (files.length > 0) {
    const file = files[0]!;
    emit('update:modelValue', String(file.id));
  }
}

/** 移除已选图片，清空值 */
function handleRemove() {
  emit('update:modelValue', '');
}
</script>

<template>
  <div class="flex items-start gap-3">
    <!-- 已选图片预览卡片 -->
    <div
      v-if="modelValue"
      class="group relative size-[120px] overflow-hidden rounded-lg border border-border"
    >
      <img
        :src="toDisplayUrl(modelValue)"
        :alt="$t('shared.common.preview')"
        class="size-full cursor-pointer object-contain"
        @click="previewVisible = true"
      />
      <!-- hover 遮罩：放大 / 删除按钮 -->
      <div
        class="absolute inset-0 flex items-center justify-center gap-2 bg-black/40 opacity-0 transition-opacity duration-200 group-hover:opacity-100"
      >
        <Button
          type="text"
          size="small"
          class="!size-8 !min-w-0 !rounded-full !bg-white/20 !text-white hover:!bg-white/40"
          @click="previewVisible = true"
        >
          <IconifyIcon icon="lucide:zoom-in" class="text-sm" />
        </Button>
        <Button
          type="text"
          size="small"
          class="!size-8 !min-w-0 !rounded-full !bg-white/20 !text-white hover:!bg-white/40"
          @click="handleRemove"
        >
          <IconifyIcon icon="lucide:trash-2" class="text-sm" />
        </Button>
      </div>
    </div>

    <!-- 选择 / 更换按钮 -->
    <Button @click="openPicker">
      <template #icon>
        <IconifyIcon icon="lucide:image-plus" />
      </template>
      {{ modelValue ? $t('shared.common.change') : $t('shared.common.select') }}
    </Button>

    <!--
      用 Form.ItemRest 包裹 FilePicker 和 Image，
      防止 Ant Design Form.Item 误收集内部表单控件（Upload/Input）导致警告
    -->
    <Form.ItemRest>
      <FilePicker
        ref="filePickerRef"
        :accept="accept"
        :image-only="imageOnly"
        @select="handleSelect"
      />

      <!-- 隐藏的 Image 组件，仅用于控制 antd 图片预览弹窗 -->
      <Image
        v-if="modelValue"
        :src="toPreviewUrl(modelValue)"
        :preview="{
          visible: previewVisible,
          onVisibleChange: (v: boolean) => (previewVisible = v),
        }"
        class="hidden"
      />
    </Form.ItemRest>
  </div>
</template>

