import type { AnyPromiseFunction } from '@vben/types';

/**
 * 成员管理 - 表单配置
 * 遵循 vben-admin 规范，独立于具体视图页面
 */
import type { VbenFormSchema } from '#/adapter/form';

import { z } from '#/adapter/form';
import { $t } from '#/locales';

/** 角色树 API 类型 */
export type RoleTreeApi = AnyPromiseFunction<any, any>;

/**
 * 管理员新建/编辑表单 Schema
 * @param options 配置选项
 */
export function useAdminFormSchema(options: {
  /** 是否编辑模式 */
  isEdit?: boolean;
  /** 当前组织节点 ID（用于默认选中） */
  nodeId?: null | number;
  /** 组织节点名称（用于默认显示） */
  nodeName?: string;
  /** 角色树 API（可选择角色） */
  roleTreeApi?: RoleTreeApi;
}): VbenFormSchema[] {
  const { isEdit = false, nodeName, nodeId, roleTreeApi } = options;

  return [
    // === 基本信息 ===
    {
      component: 'Divider',
      componentProps: {
        orientation: 'left',
      },
      fieldName: 'divider_basic',
      label: '',
      renderComponentContent: () => ({
        default: () => $t('admin.common.basicInfo'),
      }),
    },
    {
      component: 'Input',
      componentProps: {
        disabled: isEdit,
        placeholder: $t('admin.system.admin.placeholder.inputUsername'),
      },
      fieldName: 'username',
      label: $t('admin.system.admin.username'),
      rules: isEdit ? undefined : 'required',
      help: isEdit
        ? $t('admin.system.admin.help.usernameEdit')
        : $t('admin.system.admin.help.usernameCreate'),
    },
    {
      component: 'Input',
      componentProps: {
        placeholder: $t('admin.system.admin.placeholder.inputNickname'),
      },
      fieldName: 'nickname',
      label: $t('admin.system.admin.nickname'),
    },
    // 密码字段仅在新建模式显示
    ...(isEdit
      ? []
      : [
          {
            component: 'Input',
            componentProps: {
              placeholder: $t('admin.system.admin.placeholder.inputPassword'),
              type: 'password',
            },
            fieldName: 'password',
            label: $t('admin.system.admin.password'),
            rules: 'required',
          },
        ]),
    // === 联系方式 ===
    {
      component: 'Divider',
      componentProps: {
        orientation: 'left',
      },
      fieldName: 'divider_contact',
      label: '',
      renderComponentContent: () => ({
        default: () => $t('admin.common.contactInfo'),
      }),
    },
    {
      component: 'Input',
      componentProps: {
        placeholder: $t('admin.system.admin.placeholder.inputEmail'),
      },
      fieldName: 'email',
      label: $t('admin.system.admin.email'),
      rules: 'required',
    },
    {
      component: 'Input',
      componentProps: {
        placeholder: $t('admin.system.admin.placeholder.inputPhone'),
      },
      fieldName: 'phone',
      label: $t('admin.system.admin.phone'),
    },
    // === 权限设置 ===
    {
      component: 'Divider',
      componentProps: {
        orientation: 'left',
      },
      fieldName: 'divider_permission',
      label: '',
      renderComponentContent: () => ({
        default: () => $t('admin.common.permissionSettings'),
      }),
    },
    // 角色选择：若提供 roleTreeApi，则显示可选下拉树，默认选中当前节点；否则显示只读文本
    ...(roleTreeApi
      ? [
          {
            component: 'ApiTreeSelect',
            componentProps: {
              api: roleTreeApi,
              childrenField: 'children',
              labelField: 'name',
              valueField: 'id',
              placeholder: $t('admin.system.admin.placeholder.selectRole'),
              showSearch: true,
              treeNodeFilterProp: 'name',
              treeDefaultExpandAll: true,
              allowClear: true,
              style: { width: '100%' },
            },
            fieldName: 'role_id',
            label: $t('admin.system.admin.role'),
            rules: 'required',
            defaultValue: nodeId ?? undefined,
          },
        ]
      : nodeName
        ? [
            {
              component: 'Input',
              componentProps: {
                disabled: true,
              },
              fieldName: 'role_display',
              label: $t('admin.system.admin.role'),
              defaultValue: nodeName,
              help: $t('admin.system.admin.help.roleAutoBinding'),
            },
          ]
        : []),
    {
      component: 'RadioGroup',
      componentProps: {
        buttonStyle: 'solid',
        optionType: 'button',
        options: [
          { label: $t('admin.common.enabled'), value: true },
          { label: $t('admin.common.disabled'), value: false },
        ],
      },
      defaultValue: true,
      fieldName: 'is_active',
      label: $t('admin.common.accountStatus'),
    },
  ];
}

/**
 * 管理员表单默认值（新建模式）
 * @param nodeName 组织节点名称
 * @param nodeId 组织节点 ID（用于默认选中角色）
 */
export function getAdminFormDefaults(
  nodeName?: string,
  nodeId?: null | number,
): Record<string, any> {
  return {
    is_active: true,
    role_display: nodeName || $t('admin.common.notSelected'),
    role_id: nodeId ?? undefined,
  };
}

/**
 * 重置密码表单 Schema
 * 密码一致性校验通过 Zod dependencies 实现
 */
export function useResetPasswordSchema(): VbenFormSchema[] {
  return [
    {
      component: 'InputPassword',
      componentProps: {
        placeholder: $t('admin.system.admin.placeholder.inputNewPassword'),
      },
      fieldName: 'new_password',
      label: $t('admin.system.admin.newPassword'),
      rules: z.string().min(6, $t('admin.system.admin.validation.passwordMin')),
    },
    {
      component: 'InputPassword',
      componentProps: {
        placeholder: $t('admin.system.admin.placeholder.confirmPassword'),
      },
      fieldName: 'confirm_password',
      label: $t('admin.system.admin.confirmPassword'),
      dependencies: {
        triggerFields: ['new_password'],
        rules: (values) =>
          z
            .string()
            .min(1, $t('admin.system.admin.validation.confirmRequired'))
            .refine((v) => v === values.new_password, {
              message: $t('admin.system.admin.messages.passwordMismatch'),
            }),
      },
    },
  ];
}

/**
 * Novus 基础组件库
 * 存放项目通用的自定义组件，与 Vben 框架组件隔离。
 */

// 示例：导出组件
// export { default as NovusCard } from './card/index.vue';

import type { Ref } from 'vue';

/**
 * 声明式 CRUD 抽屉/弹窗 Composable
 *
 * 配合 useCrudPage 使用，自动处理：
 * - create/update 请求
 * - 表单重置
 * - Schema 切换
 * - 编辑模式数据填充 (自动 camelCase ↔ snake_case)
 *
 * @example
 * ```ts
 * // 标准用法
 * const { Drawer, isEdit } = useCrudDrawer<TenantInfo>({
 *   formApi,
 *   schema: useFormSchema,
 *   // 只需定义字段名，自动处理映射
 *   fields: ['name', 'contact_name', 'contact_phone', 'plan_id'],
 *   onSuccess: () => emits('success'),
 * });
 * ```
 */
import type { FormMode } from '#/adapter/vxe-table';

import { computed, nextTick, ref, unref } from 'vue';

import { useVbenDrawer } from '@vben/common-ui';

import { $t } from '#/locales';
import { requestClient } from '#/utils/request';

// ============ 字段映射工具函数 ============

/** snake_case 转 camelCase */
function snakeToCamel(str: string): string {
  return str.replaceAll(/_([a-z])/g, (_, letter) => letter.toUpperCase());
}

/**
 * 根据字段列表生成 toFormValues 函数
 * 后端 camelCase -> 表单 snake_case
 */
function createToFormValues<T>(
  fields: string[],
): (data: T) => Record<string, any> {
  return (data: T) => {
    const result: Record<string, any> = {};
    for (const field of fields) {
      const camelField = snakeToCamel(field);
      // @ts-ignore
      result[field] = data[camelField] ?? data[field];
    }
    return result;
  };
}

/**
 * 根据字段列表生成 transform 函数
 * 表单 snake_case -> API snake_case（空值转 null）
 */
function createTransform(
  fields: string[],
): (values: Record<string, any>) => Record<string, any> {
  return (values: Record<string, any>) => {
    const result: Record<string, any> = {};
    for (const field of fields) {
      const value = values[field];
      // 空字符串转为 null
      result[field] = value === '' || value === undefined ? null : value;
    }
    return result;
  };
}

/**
 * useCrudDrawer 配置选项
 */
export interface UseCrudDrawerOptions<T = any> {
  /** Form API（由 useVbenForm 返回）- 详情页模式可不传 */
  formApi?: {
    getValues: () => Promise<Record<string, any>>;
    resetForm: () => Promise<void>;
    setState: (state: { schema?: any[] }) => void;
    setValues: (values: Record<string, any>) => void;
    validate: () => Promise<{ valid: boolean }>;
  };

  /**
   * Schema 工厂函数
   * @param isEdit 是否编辑模式
   */
  schema?: (isEdit: boolean) => any[];

  /**
   * 字段列表（推荐）
   *
   * 提供字段列表后，自动处理：
   * - 编辑模式：后端 camelCase -> 表单 snake_case
   * - 提交时：表单 snake_case -> API snake_case（空值转 null）
   *
   * @example
   * ```ts
   * fields: ['name', 'contact_name', 'contact_phone', 'plan_id', 'expires_at']
   * ```
   */
  fields?: string[];

  /**
   * API 资源路径（可选）
   *
   * 指定后，openNew/openEdit 会自动使用此路径，无需每次传递 _resource
   */
  apiPath?: (() => string) | Ref<string> | string;

  /**
   * 数据转换函数（表单值 -> API 请求体）
   *
   * 如果提供了 `fields`，则此项可省略
   *
   * @param values 表单原始值
   * @param isEdit 是否编辑模式
   */
  transform?: (
    values: Record<string, any>,
    isEdit: boolean,
  ) => Record<string, any>;

  /**
   * 新建模式的表单默认值
   * 可以是静态对象或工厂函数
   */
  defaults?: (() => Record<string, any>) | Record<string, any>;

  /**
   * 后端数据 -> 表单值（编辑模式）
   *
   * 如果提供了 `fields`，则此项可省略
   *
   * @param data 后端返回的数据
   */
  toFormValues?: (data: T) => Record<string, any>;

  /** 成功回调 */
  onSuccess?: () => void;

  /**
   * 保存后回调（可选）
   *
   * 在 API 请求成功后、onSuccess 之前调用。
   * 可用于保存关联数据（如技能脚本）。
   *
   * @param response API 响应数据
   * @param formValues 表单原始值
   * @param isEdit 是否编辑模式
   */
  afterSave?: (
    response: any,
    formValues: Record<string, any>,
    isEdit: boolean,
  ) => Promise<void> | void;

  /** 打开时额外操作（如加载远程数据） */
  onOpen?: () => Promise<void> | void;

  /** 打开后额外操作（如更新下拉选项） */
  afterOpen?: (formApi: any, isEdit: boolean) => Promise<void> | void;

  /**
   * 详情 API（可选）
   *
   * 提供后，编辑模式会调用此 API 获取完整数据，而不是使用列表传递的行数据
   */
  detailApi?: (id: number | string) => Promise<T>;

  /**
   * 主键字段名
   * @default 'id'
   */
  idField?: string;
}

/**
 * 一体化 CRUD 抽屉
 * 整合 useVbenDrawer + useCrudForm，简化表单组件
 */
export function useCrudDrawer<T = any>(options: UseCrudDrawerOptions<T>) {
  const {
    formApi,
    schema,
    fields,
    transform: customTransform,
    defaults,
    toFormValues: customToFormValues,
    onSuccess,
    afterSave,
    onOpen,
    afterOpen,
    apiPath,
    detailApi,
    idField = 'id',
  } = options;

  // 如果提供了 fields，自动生成 transform 和 toFormValues
  const transform =
    customTransform ?? (fields ? createTransform(fields) : (v: any) => v);
  const toFormValues =
    customToFormValues ?? (fields ? createToFormValues<T>(fields) : undefined);

  const mode = ref<FormMode>('add');
  const recordId = ref<number | string>();
  const resource = ref<string>('');
  const rowData = ref<T>();
  /** 详情数据（通过 detailApi 获取） */
  const detailData = ref<T>();

  const isEdit = computed(() => mode.value === 'edit');

  // 防抖状态
  const isSubmitting = ref(false);

  const [Drawer, drawerApi] = useVbenDrawer({
    async onConfirm() {
      // 防抖：如果正在提交中，直接返回
      if (isSubmitting.value) return;

      if (!formApi) return;

      const { valid } = await formApi.validate();
      if (!valid) return;

      const values = await formApi.getValues();
      const requestData = transform(values, isEdit.value);

      isSubmitting.value = true;
      drawerApi.lock();

      try {
        const response = await (isEdit.value && recordId.value
          ? requestClient.put(
              `${resource.value}/${recordId.value}`,
              requestData,
              {
                showSuccessMessage: true,
                successMessage: $t('ui.actionMessage.updateSuccess'),
              },
            )
          : requestClient.post(resource.value, requestData, {
              showSuccessMessage: true,
              successMessage: $t('ui.actionMessage.createSuccess'),
            }));
        if (afterSave) {
          await afterSave(response, values, isEdit.value);
        }
        await onSuccess?.();
        drawerApi.close();
      } catch {
        drawerApi.unlock();
      } finally {
        isSubmitting.value = false;
      }
    },

    async onOpenChange(isOpen) {
      if (!isOpen) return;

      // 从 drawerApi 获取数据
      const data = drawerApi.getData() as
        | (T & {
            [key: string]: any;
            _defaults?: Record<string, any>;
            _resource?: string;
            id?: number | string;
            mode?: FormMode;
          })
        | undefined;
      mode.value = data?.mode ?? 'add';
      recordId.value = data?.[idField];
      {
        const p = unref(apiPath) as (() => string) | string | undefined;
        const resolved = typeof p === 'function' ? p() : p;
        resource.value = data?._resource ?? resolved ?? '';
      }
      rowData.value = data as T;

      // 重置表单
      await formApi?.resetForm();

      // 执行 onOpen（如加载远程数据）
      await onOpen?.();

      // 更新 schema
      if (schema && formApi) {
        formApi.setState({ schema: schema(isEdit.value) });
      }
      await nextTick();

      // 执行 afterOpen（如更新下拉选项）
      await afterOpen?.(formApi, isEdit.value);

      // 填充表单数据
      if (isEdit.value || mode.value === 'view') {
        // 编辑或查看模式：优先调用详情 API 获取完整数据
        let fetchedData: T | undefined = data as T;
        if (detailApi && recordId.value) {
          try {
            drawerApi.setState({ loading: true });
            fetchedData = await detailApi(recordId.value);
            detailData.value = fetchedData;
          } catch {
            // 详情加载失败，回退到行数据
            fetchedData = data as T;
          } finally {
            drawerApi.setState({ loading: false });
          }
        }
        if (toFormValues && fetchedData && formApi) {
          formApi.setValues(toFormValues(fetchedData));
        }
      } else {
        // 新建模式：优先使用 _defaults（从 useCrudPage 传入），否则使用本地 defaults 配置
        const defaultValues =
          data?._defaults ??
          (typeof defaults === 'function' ? defaults() : defaults);
        if (defaultValues && formApi) {
          formApi.setValues(defaultValues);
        }
      }
    },
  });

  /**
   * 打开新建模式
   * @param extraData 额外传递给 Drawer 的数据
   */
  function openNew(extraData?: Record<string, any>) {
    const p = unref(apiPath) as (() => string) | string | undefined;
    const path = typeof p === 'function' ? p() : p;
    drawerApi
      .setData({
        mode: 'add',
        ...(path ? { _resource: path } : {}),
        ...extraData,
      })
      .open();
  }

  /**
   * 打开编辑模式
   * @param record 要编辑的记录
   * @param extraData 额外传递给 Drawer 的数据
   */
  function openEdit(record: Partial<T>, extraData?: Record<string, any>) {
    const p = unref(apiPath) as (() => string) | string | undefined;
    const path = typeof p === 'function' ? p() : p;
    drawerApi
      .setData({
        ...record,
        mode: 'edit',
        ...(path ? { _resource: path } : {}),
        ...extraData,
      })
      .open();
  }

  return {
    Drawer,
    drawerApi,
    isEdit,
    mode,
    recordId,
    resource,
    rowData,
    detailData,
    openNew,
    openEdit,
  };
}

/**
 * 声明式 CRUD 列表 Composable — 无渲染数据层
 *
 * 提供完整的列表数据管理能力（加载、搜索、分页、CRUD、回收站），
 * 但不绑定任何渲染组件（VxeTable / Card / 等），
 * 页面可自由选择渲染方式（卡片网格、配置面板、Master-Detail 等）。
 *
 * @example 卡片网格
 * ```ts
 * const {
 *   list, total, loading, currentPage,
 *   FormDrawer, onCreate, onEdit, onDelete,
 *   onSearch, onPageChange,
 * } = useCrudList<KBItem>({
 *   api: { list: getListApi, resource: '/admin/ai/knowledge-bases' },
 *   formComponent: KBForm,
 *   i18nPrefix: 'admin.knowledgeBase',
 *   pageSize: 12,
 *   createPermission: 'ai_knowledge_base:create',
 * });
 * ```
 *
 * @example Master-Detail（配合 selectable）
 * ```ts
 * const {
 *   list, selectedId, selectedItem, onSelect,
 * } = useCrudList<PackageInfo>({
 *   api: { list: getPackageListApi, resource: '/admin/ai/skill-packages' },
 *   i18nPrefix: 'admin.ai.skillPackage',
 *   selectable: true,
 *   defaultSelect: 'first',
 *   clientFilter: (item, kw) => item.name.toLowerCase().includes(kw),
 * });
 * ```
 */

import type { Component, ComputedRef, Ref } from 'vue';

import { computed, h, onBeforeUnmount, onMounted, ref } from 'vue';

import { useVbenDrawer, useVbenModal } from '@vben/common-ui';

import { message, Modal } from 'ant-design-vue';

import { $t } from '#/locales';
import { requestClient } from '#/utils/request';

// ============================================================
// 依赖阻止类型 & 命令式弹窗
// ============================================================

interface DependencyItem {
  id: number;
  label?: string;
}

interface DependencyGroup {
  type: string;
  count: number;
  items: DependencyItem[];
}

const DEP_MAX_PREVIEW = 5;

/** 命令式显示依赖阻止弹窗（无需组件 ref） */
function showDependencyBlock(deps: DependencyGroup[], name: string) {
  const title = name
    ? `${$t('common.dependency.title')}「${name}」`
    : $t('common.dependency.title');

  Modal.warning({
    title,
    width: 520,
    centered: true,
    content: () =>
      h('div', {}, [
        h(
          'div',
          {
            class:
              'mb-3 rounded-lg bg-warning/10 px-4 py-3 text-sm text-foreground',
          },
          $t('common.dependency.blocked'),
        ),
        ...deps.map((dep) =>
          h(
            'div',
            {
              key: dep.type,
              class:
                'mb-2 rounded-lg border border-border/50 bg-accent/5 px-4 py-3',
            },
            [
              h(
                'div',
                {
                  class:
                    'mb-1 flex items-center justify-between text-sm font-medium',
                },
                [
                  h('span', {}, $t(`common.dependency.model.${dep.type}`)),
                  h('span', { class: 'text-xs text-warning' }, `${dep.count}`),
                ],
              ),
              ...(dep.items || []).slice(0, DEP_MAX_PREVIEW).map((item) =>
                h(
                  'div',
                  {
                    key: item.id,
                    class: 'pl-2 text-xs text-muted-foreground',
                  },
                  `• ${item.label || `#${item.id}`}`,
                ),
              ),
              dep.count > DEP_MAX_PREVIEW
                ? h(
                    'div',
                    { class: 'pl-2 text-xs italic text-muted-foreground/60' },
                    $t('common.dependency.moreItems', {
                      count: dep.count - DEP_MAX_PREVIEW,
                    }),
                  )
                : null,
            ],
          ),
        ),
        h(
          'div',
          {
            class:
              'mt-3 rounded-lg bg-primary/5 px-4 py-2.5 text-xs text-muted-foreground',
          },
          $t('common.dependency.description'),
        ),
      ]),
  });
}

// ============================================================
// 类型定义
// ============================================================

/** 切换状态 API 类型 */
export type ToggleStatusApi = (
  id: number | string,
  data: Record<string, unknown>,
) => Promise<unknown>;

/** 切换状态配置 */
export type ToggleStatusConfig = Record<string, ToggleStatusApi>;

/** API 配置 */
export interface CrudListApiConfig<T = unknown> {
  /** 列表查询 API（必填） */
  list: (
    params: Record<string, unknown>,
  ) => Promise<T[] | { items: T[]; total: number }>;

  /**
   * 资源基础路径（必填）
   * 用于自动构造 DELETE 请求：DELETE {resource}/{id}
   */
  resource: string;

  /**
   * 自定义删除 API（可选）
   * 如不提供，将使用 resource 路径自动构造 DELETE 请求
   */
  delete?: (id: number) => Promise<void>;

  /**
   * 快捷开关配置（支持多个）
   * @example { is_active: toggleStatusApi }
   */
  toggles?: ToggleStatusConfig;
}

/** 回收站配置 */
export interface RecycleBinConfig {
  nameField?: string;
  columns?: Array<{ dataIndex: string; title: string; width?: number }>;
}

/** useCrudList 配置选项 */
export interface UseCrudListOptions<
  T extends object = Record<string, unknown>,
> {
  /**
   * 主键字段名
   * @default 'id'
   * @example 'feature_code' | 'provider_id'
   */
  keyField?: string;
  /** API 配置（必填） */
  api: CrudListApiConfig<T>;

  /**
   * API 响应适配器
   * 用于处理非标准 API 响应（如返回数组而非 {items, total}）
   * @default 自动检测：数组包装为 { items: data, total: data.length }
   */
  responseAdapter?: (data: unknown) => { items: T[]; total: number };

  /** 表单组件 */
  formComponent?: Component;

  /** 表单类型：drawer 或 modal，默认 drawer */
  formType?: 'drawer' | 'modal';

  /**
   * 新建模式的表单默认值
   */
  formDefaults?: (() => Record<string, unknown>) | Record<string, unknown>;

  /**
   * 客户端过滤函数
   * 启用后，列表一次加载全量数据，搜索在前端过滤
   */
  clientFilter?: (item: T, keyword: string) => boolean;

  /** 固定过滤条件（每次请求都会附带） */
  defaultFilters?: Record<string, unknown>;

  /** 默认排序字段，默认 '-created_at' */
  defaultSort?: string;

  /** 每页条数，默认 20 */
  pageSize?: number;

  /** 是否启用分页，默认 true */
  pager?: boolean;

  /**
   * 自动刷新间隔（毫秒）
   * 0 或不设置 = 不自动刷新
   */
  autoRefreshInterval?: number;

  /**
   * 是否启用选中状态（Master-Detail 模式）
   * @default false
   */
  selectable?: boolean;

  /**
   * 默认选中策略
   * - 'first': 加载后自动选中第一条
   * - 'none': 不自动选中
   * @default 'first'
   */
  defaultSelect?: 'first' | 'none';

  /** i18n 前缀（必填） */
  i18nPrefix: string;

  /** 用于显示的名称字段，默认 'name' */
  nameField?: keyof T & string;

  /** 创建按钮权限码 */
  createPermission?: string;

  /**
   * 回收站配置
   * - true: 启用回收站，使用默认配置
   * - RecycleBinConfig: 启用并自定义
   * - false/undefined: 不启用
   */
  recycleBin?: boolean | RecycleBinConfig;

  /** 自定义操作处理器 */
  customActions?: Record<string, (row: T) => void>;
}

/** useCrudList 返回值 */
export interface UseCrudListReturn<T extends object = Record<string, unknown>> {
  // === 响应式数据 ===
  list: Ref<T[]>;
  filteredList: ComputedRef<T[]>;
  total: Ref<number>;
  loading: Ref<boolean>;
  currentPage: Ref<number>;
  pageSize: Ref<number>;
  searchKeyword: Ref<string>;
  searchParams: Ref<Record<string, unknown>>;

  // === 选中状态 ===
  selectedId: Ref<null | number | string>;
  selectedItem: ComputedRef<null | T>;

  // === 组件 ===
  FormDrawer: Component | null;
  formApi:
    | null
    | ReturnType<typeof useVbenDrawer>[1]
    | ReturnType<typeof useVbenModal>[1];
  // === CRUD 操作 ===
  loadList: () => Promise<void>;
  reload: () => Promise<void>;
  onCreate: () => void;
  onEdit: (row: T) => void;
  onDelete: (row: T) => Promise<void>;
  onToggleStatus: (newStatus: boolean, row: T) => Promise<boolean>;
  onToggleField: (
    fieldName: string,
    newStatus: boolean,
    row: T,
  ) => Promise<boolean>;
  onSelect: (row: T) => void;

  // === 搜索/分页 ===
  onSearch: (params?: Record<string, unknown>) => void;
  onPageChange: (page: number) => void;
  onPageSizeChange: (size: number) => void;

  // === 回收站 ===
  openRecycleBin: () => void;
  recycleBinCount: Ref<number>;

  // === 辅助 ===
  isProcessing: (id: number | string) => boolean;
  handleMenuAction: (code: string, row: T) => void;

  // === 生命周期 ===
  startAutoRefresh: () => void;
  stopAutoRefresh: () => void;
}

// ============================================================
// 依赖阻止错误码
// ============================================================
const DEPENDENCY_BLOCKED_CODE = 4221;

// ============================================================
// 默认响应适配器：自动检测数组/分页格式
// ============================================================
function defaultResponseAdapter<T>(data: unknown): {
  items: T[];
  total: number;
} {
  if (Array.isArray(data)) {
    return { items: data as T[], total: data.length };
  }
  const obj = data as Record<string, unknown>;
  if (obj && Array.isArray(obj.items)) {
    return {
      items: obj.items as T[],
      total: (obj.total as number) ?? obj.items.length,
    };
  }
  return { items: [], total: 0 };
}

// ============================================================
// 日期范围处理（复用自 useCrudPage）
// ============================================================
function processFormValues(
  formValues: Record<string, unknown>,
): Record<string, unknown> {
  const result: Record<string, unknown> = {};

  for (const [key, value] of Object.entries(formValues)) {
    if (key.startsWith('_dateRange_') && Array.isArray(value)) {
      const field = key.replace('_dateRange_', '');
      const [startDate, endDate] = value;
      if (startDate && endDate) {
        result[`filter[${field}][between]`] = `${startDate},${endDate}`;
      } else if (startDate) {
        result[`filter[${field}][gte]`] = startDate;
      } else if (endDate) {
        result[`filter[${field}][lte]`] = endDate;
      }
    } else if (value !== undefined && value !== null && value !== '') {
      result[key] = value;
    }
  }

  return result;
}

// ============================================================
// useCrudList 实现
// ============================================================

export function useCrudList<T extends object = Record<string, unknown>>(
  options: UseCrudListOptions<T>,
): UseCrudListReturn<T> {
  const {
    api,
    responseAdapter = defaultResponseAdapter,
    formComponent,
    formType = 'drawer',
    formDefaults,
    clientFilter,
    defaultFilters = {},
    defaultSort = '-created_at',
    pageSize: initialPageSize = 20,
    pager = true,
    autoRefreshInterval = 0,
    selectable = false,
    defaultSelect = 'first',
    i18nPrefix,
    keyField = 'id',
    nameField = 'name' as keyof T & string,
    customActions = {},
  } = options;

  /** 获取行主键值 */
  function getRowKey(row: T): number | string {
    return (row as Record<string, unknown>)[keyField] as number | string;
  }

  // ==================== 响应式状态 ====================
  const list = ref<T[]>([]) as Ref<T[]>;
  const total = ref(0);
  const loading = ref(false);
  const currentPage = ref(1);
  const pageSize = ref(initialPageSize);
  const searchKeyword = ref('');
  const searchParams = ref<Record<string, unknown>>({});

  // ==================== 选中状态 ====================
  const selectedId = ref<null | number | string>(null);
  const selectedItem = computed<null | T>(() => {
    if (!selectable || selectedId.value === null) return null;
    return (
      list.value.find((item) => getRowKey(item) === selectedId.value) ?? null
    );
  });

  function onSelect(row: T) {
    selectedId.value = getRowKey(row);
  }

  // ==================== 客户端过滤 ====================
  const filteredList = computed<T[]>(() => {
    if (!clientFilter || !searchKeyword.value.trim()) {
      return list.value;
    }
    const kw = searchKeyword.value.toLowerCase().trim();
    return list.value.filter((item) => clientFilter(item, kw));
  });

  // ==================== 列表加载 ====================
  async function loadList() {
    loading.value = true;
    try {
      let result: { items: T[]; total: number };

      if (clientFilter) {
        // 客户端过滤模式：加载全量数据
        const rawData = await api.list({
          'page[size]': 9999,
          sort: defaultSort,
          ...defaultFilters,
        });
        result = responseAdapter(rawData);
      } else {
        // 服务端分页模式
        const processedParams = processFormValues(searchParams.value);
        const params: Record<string, unknown> = {
          ...processedParams,
          ...defaultFilters,
          sort: defaultSort,
        };
        if (pager) {
          params['page[number]'] = currentPage.value;
          params['page[size]'] = pageSize.value;
        } else {
          params['page[size]'] = 9999;
        }
        const rawData = await api.list(params);
        result = responseAdapter(rawData);
      }

      list.value = result.items;
      total.value = result.total;

      // 选中状态处理
      if (
        selectable &&
        list.value.length > 0 &&
        (selectedId.value === null ||
          !list.value.some((item) => getRowKey(item) === selectedId.value)) &&
        defaultSelect === 'first'
      ) {
        selectedId.value = getRowKey(list.value[0]!);
      }
    } catch {
      list.value = [];
      total.value = 0;
    } finally {
      loading.value = false;
    }
  }

  async function reload() {
    currentPage.value = 1;
    await loadList();
  }

  // ==================== 搜索 ====================
  function onSearch(params?: Record<string, unknown>) {
    if (params) {
      searchParams.value = params;
    }
    currentPage.value = 1;
    loadList();
  }

  function onPageChange(page: number) {
    currentPage.value = page;
    loadList();
  }

  function onPageSizeChange(size: number) {
    pageSize.value = size;
    currentPage.value = 1;
    loadList();
  }

  // ==================== 表单弹窗 ====================
  let FormPopup:
    | null
    | ReturnType<typeof useVbenDrawer>[0]
    | ReturnType<typeof useVbenModal>[0] = null;
  let formPopupApi:
    | null
    | ReturnType<typeof useVbenDrawer>[1]
    | ReturnType<typeof useVbenModal>[1] = null;

  if (formComponent) {
    if (formType === 'modal') {
      const [ModalComp, modalApi] = useVbenModal({
        connectedComponent: formComponent,
        destroyOnClose: true,
      });
      FormPopup = ModalComp;
      formPopupApi = modalApi;
    } else {
      const [DrawerComp, drawerApi] = useVbenDrawer({
        connectedComponent: formComponent,
        destroyOnClose: true,
      });
      FormPopup = DrawerComp;
      formPopupApi = drawerApi;
    }
  }

  function onCreate() {
    const defaults =
      typeof formDefaults === 'function' ? formDefaults() : formDefaults;
    formPopupApi
      ?.setData({
        mode: 'add',
        _resource: api.resource,
        _defaults: defaults,
      })
      .open();
  }

  function onEdit(row: T) {
    formPopupApi
      ?.setData({ ...row, mode: 'edit', _resource: api.resource })
      .open();
  }

  // ==================== 防抖状态 ====================
  const processingIds = ref<Set<number | string>>(new Set());

  function isProcessing(id: number | string): boolean {
    return processingIds.value.has(id);
  }

  function setProcessing(id: number | string, processing: boolean) {
    if (processing) {
      processingIds.value.add(id);
    } else {
      processingIds.value.delete(id);
    }
  }

  // ==================== 删除 ====================
  async function onDelete(row: T) {
    const rowId = getRowKey(row);
    if (isProcessing(rowId)) return;

    setProcessing(rowId, true);
    try {
      await (api.delete
        ? api.delete(rowId as number)
        : requestClient.delete(`${api.resource}/${rowId}`, {
            loading: true,
            showCodeMessage: false,
            showSuccessMessage: true,
            successMessage: $t(`${i18nPrefix}.messages.deleteSuccess`),
          }));
      await loadList();
    } catch (error: unknown) {
      const resp = (error as Record<string, unknown>)?.response as
        | Record<string, unknown>
        | undefined;
      const data = resp?.data as Record<string, unknown> | undefined;
      if (data?.code === DEPENDENCY_BLOCKED_CODE && data?.dependencies) {
        const displayName = String(row[nameField] || rowId);
        showDependencyBlock(
          data.dependencies as DependencyGroup[],
          displayName,
        );
      } else if (data?.message) {
        message.error(String(data.message));
      }
    } finally {
      setProcessing(rowId, false);
    }
  }

  // ==================== Toggle 状态 ====================
  async function onToggleField(
    fieldName: string,
    newStatus: boolean,
    row: T,
  ): Promise<boolean> {
    const rowId = getRowKey(row);
    if (isProcessing(rowId)) return false;

    const toggleApi = api.toggles?.[fieldName] as ToggleStatusApi | undefined;
    if (!toggleApi) return false;

    const displayName = String(row[nameField] || rowId);
    const action = newStatus
      ? $t('admin.common.enable')
      : $t('admin.common.disable');

    try {
      await new Promise<void>((resolve, reject) => {
        Modal.confirm({
          title: $t(`${i18nPrefix}.messages.toggleStatusTitle`),
          content: $t(`${i18nPrefix}.messages.toggleStatusConfirm`, {
            action,
            name: displayName,
          }),
          onOk: () => resolve(),
          onCancel: () => reject(new Error('cancelled')),
        });
      });

      setProcessing(rowId, true);
      try {
        await toggleApi(rowId, { [fieldName]: newStatus });
        message.success(`${action}${$t('ui.actionMessage.operationSuccess')}`);
        await loadList();
        return true;
      } finally {
        setProcessing(rowId, false);
      }
    } catch {
      return false;
    }
  }

  async function onToggleStatus(newStatus: boolean, row: T): Promise<boolean> {
    return onToggleField('is_active', newStatus, row);
  }

  // ==================== 回收站 ====================
  const recycleBinCount = ref(0);

  function openRecycleBin() {
    // noop — 页面自行管理 RecycleBinDrawer ref 和 open()
  }

  // ==================== 操作分发 ====================
  function handleMenuAction(code: string, row: T) {
    const customAction = customActions[code];
    if (customAction) {
      customAction(row);
      return;
    }

    switch (code) {
      case 'delete': {
        onDelete(row);
        break;
      }
      case 'edit': {
        onEdit(row);
        break;
      }
    }
  }

  // ==================== 自动刷新 ====================
  let refreshTimer: null | ReturnType<typeof setInterval> = null;

  function startAutoRefresh() {
    stopAutoRefresh();
    if (autoRefreshInterval > 0) {
      refreshTimer = setInterval(loadList, autoRefreshInterval);
    }
  }

  function stopAutoRefresh() {
    if (refreshTimer) {
      clearInterval(refreshTimer);
      refreshTimer = null;
    }
  }

  // ==================== 生命周期 ====================
  onMounted(() => {
    loadList();
    if (autoRefreshInterval > 0) {
      startAutoRefresh();
    }
  });

  onBeforeUnmount(() => {
    stopAutoRefresh();
  });

  // ==================== 返回 ====================
  return {
    // 响应式数据
    list,
    filteredList,
    total,
    loading,
    currentPage,
    pageSize,
    searchKeyword,
    searchParams,

    // 选中状态
    selectedId,
    selectedItem,

    // 组件
    FormDrawer: FormPopup,
    formApi: formPopupApi,

    // CRUD 操作
    loadList,
    reload,
    onCreate,
    onEdit,
    onDelete,
    onToggleStatus,
    onToggleField,
    onSelect,

    // 搜索/分页
    onSearch,
    onPageChange,
    onPageSizeChange,

    // 回收站
    openRecycleBin,
    recycleBinCount,

    // 辅助
    isProcessing,
    handleMenuAction,

    // 生命周期
    startAutoRefresh,
    stopAutoRefresh,
  };
}

/**
 * 通知 Toast 弹窗管理器
 *
 * 管理右下角 toast 通知的队列、堆叠、自动消失。
 * 由 Socket.IO 通知事件触发，尊重用户偏好。
 */
import { ref } from 'vue';

export type NotificationPriority = 'high' | 'low' | 'normal' | 'urgent';

export interface ToastItem {
  id: number;
  template_code?: null | string;
  category: string;
  title: string;
  body?: null | string;
  data?: null | Record<string, unknown>;
  link?: null | string;
  priority: NotificationPriority;
  createdAt: number;
}

const MAX_VISIBLE = 3;
const toasts = ref<ToastItem[]>([]);
const queue: ToastItem[] = [];
const timers = new Map<number, ReturnType<typeof setTimeout>>();
let idCounter = 0;

function getAutoCloseMs(priority: string): number {
  switch (priority) {
    case 'high': {
      return 8000;
    }
    case 'urgent': {
      return 0;
    }
    default: {
      return 5000;
    }
  }
}

function removeToast(id: number) {
  const timer = timers.get(id);
  if (timer) {
    clearTimeout(timer);
    timers.delete(id);
  }
  toasts.value = toasts.value.filter((t) => t.id !== id);
  // 从队列中弹出下一条
  if (queue.length > 0 && toasts.value.length < MAX_VISIBLE) {
    const next = queue.shift()!;
    toasts.value.push(next);
    scheduleAutoClose(next);
  }
}

function scheduleAutoClose(item: ToastItem) {
  const ms = getAutoCloseMs(item.priority);
  if (ms > 0) {
    const timer = setTimeout(() => {
      timers.delete(item.id);
      removeToast(item.id);
    }, ms);
    timers.set(item.id, timer);
  }
}

function pushToast(data: {
  body?: null | string;
  category: string;
  data?: null | Record<string, unknown>;
  link?: null | string;
  priority?: NotificationPriority | string;
  template_code?: null | string;
  title: string;
}) {
  const item: ToastItem = {
    id: ++idCounter,
    template_code: data.template_code,
    category: data.category,
    title: data.title,
    body: data.body,
    data: data.data,
    link: data.link,
    priority: (data.priority || 'normal') as NotificationPriority,
    createdAt: Date.now(),
  };

  if (toasts.value.length >= MAX_VISIBLE) {
    queue.push(item);
  } else {
    toasts.value.push(item);
    scheduleAutoClose(item);
  }
}

function clearAll() {
  for (const timer of timers.values()) {
    clearTimeout(timer);
  }
  timers.clear();
  toasts.value = [];
  queue.length = 0;
}

export function useNotificationToast() {
  return {
    toasts,
    pushToast,
    removeToast,
    clearAll,
  };
}

/**
 * 表格拖拽排序功能
 * 基于 sortablejs 实现，与 vxe-table 配合使用
 *
 * 设计特点：
 * 1. 每个实例独立状态，支持多表格场景
 * 2. 通过 gridApi 精确定位 DOM，不依赖全局选择器
 * 3. 提供自动初始化版本，减少模板代码
 */
import type { VxeGridInstance } from 'vxe-table';

import { nextTick, onMounted, onUnmounted } from 'vue';

import { message } from 'ant-design-vue';
import Sortable from 'sortablejs';

import { $t } from '#/locales';

/**
 * 拖拽排序配置
 */
export interface DragSortConfig {
  /**
   * 更新排序的 API 函数 (单条模式)
   * @param id 记录 ID
   * @param sortOrder 新的排序值
   * @deprecated 推荐使用 onBatchUpdate
   */
  onUpdate?: (id: number | string, sortOrder: number) => Promise<any>;

  /**
   * 批量更新排序 API (推荐)
   * @param ids 有序的 ID 列表
   */
  onBatchUpdate?: (ids: (number | string)[]) => Promise<any>;

  /**
   * 主键字段名
   * @default 'id'
   */
  keyField?: string;

  /**
   * 成功提示文本
   */
  successMessage?: string;

  /**
   * 失败提示文本
   */
  errorMessage?: string;

  /**
   * 是否禁用拖拽
   * @default false
   */
  disabled?: boolean;
}

/**
 * Grid 获取器类型
 * 支持 getter 函数或 ref 对象
 */
export type GridGetter =
  | (() => undefined | VxeGridInstance)
  | { value: undefined | VxeGridInstance };

/**
 * 拖拽排序 Composable
 *
 * 每次调用都会创建独立的状态，支持同一页面多个表格
 *
 * @example
 * ```ts
 * // 基础用法 - 需要手动初始化
 * const { initDragSort } = useTableDragSort(
 *   () => gridApi.grid,
 *   { onUpdate: (id, sortOrder) => api.updateSort(id, { sort_order: sortOrder }) }
 * );
 *
 * // 监听数据加载后初始化
 * watch(() => gridApi.grid, (grid) => {
 *   if (grid) nextTick(() => initDragSort());
 * }, { immediate: true });
 * ```
 */
export function useTableDragSort(
  gridGetter: GridGetter,
  config: DragSortConfig,
) {
  // 实例状态（闭包隔离，支持多表格）
  let sortableInstance: null | Sortable = null;
  let isInitialized = false;

  const {
    keyField = 'id',
    onUpdate,
    onBatchUpdate,
    successMessage,
    errorMessage,
  } = config;

  /** 获取 grid 实例 */
  function getGrid(): undefined | VxeGridInstance {
    return typeof gridGetter === 'function' ? gridGetter() : gridGetter.value;
  }

  /**
   * 获取表格 tbody 元素
   * 通过 grid 实例的 $el 精确定位，避免全局选择器在多表格场景下冲突
   */
  function getTableBody(): HTMLElement | null {
    const grid = getGrid();
    if (!grid?.$el) return null;
    return grid.$el.querySelector('.vxe-table--body tbody');
  }

  /** 销毁 Sortable 实例 */
  function destroy() {
    if (sortableInstance) {
      sortableInstance.destroy();
      sortableInstance = null;
    }
    isInitialized = false;
  }

  /** 刷新表格（重新查询数据） */
  async function refreshTable() {
    destroy();
    const grid = getGrid();
    if (grid) {
      grid.loadData([]);
      await nextTick();
      await grid.commitProxy('query');
      // 数据加载完成后重新初始化拖拽
      await nextTick();
      initDragSort();
    }
  }

  /** 处理拖拽结束事件 */
  async function handleDragEnd(evt: Sortable.SortableEvent) {
    const { oldIndex, newIndex } = evt;
    if (
      oldIndex === undefined ||
      newIndex === undefined ||
      oldIndex === newIndex
    ) {
      return;
    }

    const grid = getGrid();
    if (!grid) return;

    // 获取全量数据并模拟移动
    const { fullData } = grid.getTableData();
    const tableData = [...(fullData || [])];
    if (tableData.length === 0) return;

    const movedItem = tableData.splice(oldIndex, 1)[0];
    if (!movedItem) return;
    tableData.splice(newIndex, 0, movedItem);

    // 更新排序
    try {
      if (onBatchUpdate) {
        // 批量模式：发送当前页所有 ID 的新顺序
        const ids = tableData.map((item: any) => item[keyField]);
        await onBatchUpdate(ids);
      } else if (onUpdate) {
        // 单条模式：仅更新受影响的行
        const minIdx = Math.min(oldIndex, newIndex);
        const maxIdx = Math.max(oldIndex, newIndex);
        const updates: Array<{ id: number | string; sortOrder: number }> = [];

        for (let i = minIdx; i <= maxIdx; i++) {
          const item = tableData[i];
          updates.push({ id: (item as any)[keyField], sortOrder: i });
        }
        await Promise.all(updates.map((u) => onUpdate(u.id, u.sortOrder)));
      }
      message.success(successMessage || $t('shared.common.sortSuccess'));
    } catch {
      message.error(errorMessage || $t('shared.common.sortFailed'));
    } finally {
      await refreshTable();
    }
  }

  /**
   * 初始化拖拽功能
   * 在表格数据加载完成后调用
   */
  function initDragSort() {
    destroy();

    if (config.disabled) return;

    const gridEl = getTableBody();
    if (!gridEl) return;

    sortableInstance = Sortable.create(gridEl, {
      animation: 150,
      handle: '.drag-handle',
      ghostClass: 'sortable-ghost',
      onEnd: handleDragEnd,
    });

    isInitialized = true;
  }

  // 组件卸载时清理
  onUnmounted(() => {
    destroy();
  });

  return {
    /** 初始化拖拽（在数据加载完成后调用） */
    initDragSort,
    /** 销毁拖拽实例 */
    destroy,
    /** 刷新表格 */
    refreshTable,
    /** 是否已初始化 */
    get isInitialized() {
      return isInitialized;
    },
  };
}

/**
 * 拖拽排序 Composable（自动初始化版本）
 *
 * 自动等待 grid 实例可用后初始化拖拽
 * 注：gridApi.grid 不是响应式的，所以使用轮询等待
 *
 * @example
 * ```ts
 * // 与 useCrudPage 配合 - 最简用法
 * const { Grid, gridApi } = useCrudPage({ ... });
 *
 * useAutoTableDragSort(
 *   () => gridApi.grid,
 *   { onUpdate: (id, sortOrder) => api.updateSort(id, { sort_order: sortOrder }) }
 * );
 * ```
 */
export function useAutoTableDragSort(
  gridGetter: GridGetter,
  config: DragSortConfig,
) {
  const dragSort = useTableDragSort(gridGetter, config);

  let pollTimer: null | ReturnType<typeof setInterval> = null;
  let attempts = 0;
  const MAX_ATTEMPTS = 50; // 最多尝试 5 秒 (50 * 100ms)

  function stopPolling() {
    if (pollTimer) {
      clearInterval(pollTimer);
      pollTimer = null;
    }
    attempts = 0;
  }

  /**
   * 轮询等待 grid 实例可用且数据已加载
   * gridApi.grid 不是响应式的，无法用 watch 监听
   */
  function startPolling() {
    stopPolling();

    pollTimer = setInterval(() => {
      attempts++;
      const grid =
        typeof gridGetter === 'function' ? gridGetter() : gridGetter.value;

      // 检查 grid 是否已挂载
      if (grid?.$el) {
        // 检查是否有 tbody 元素（说明表格已渲染）
        const tbody = grid.$el.querySelector('.vxe-table--body tbody');
        if (tbody) {
          // 检查是否有 drag-handle（说明数据已加载）
          const handles = tbody.querySelectorAll('.drag-handle');
          if (handles.length > 0) {
            stopPolling();
            nextTick(() => {
              dragSort.initDragSort();
            });
            return;
          }
        }
      }

      // 超时处理
      if (attempts >= MAX_ATTEMPTS) {
        stopPolling();
      }
    }, 100);
  }

  // 组件挂载后开始轮询
  onMounted(() => {
    startPolling();
  });

  // 组件卸载时清理
  onUnmounted(() => {
    stopPolling();
    dragSort.destroy();
  });

  // @ts-ignore
  if (import.meta.hot) {
    // @ts-ignore
    import.meta.hot.dispose(() => {
      stopPolling();
      dragSort.destroy();
    });
  }

  return dragSort;
}

/**
 * 拖拽列定义
 *
 * 在列配置中添加此列以显示拖拽手柄
 * 注：DragHandle 渲染器在 renderers.ts 中注册
 *
 * @example
 * ```ts
 * const columns = [
 *   dragColumn,  // 拖拽手柄列
 *   { field: 'name', title: '名称' },
 *   // ...
 * ];
 * ```
 */
export const dragColumn = {
  field: '_drag',
  title: '',
  width: 40,
  align: 'center' as const,
  cellRender: {
    name: 'DragHandle',
  },
};

import type { Router } from 'vue-router';

import type { ApiEndpoint } from '#/api';

import { preferences } from '@vben/preferences';
import { useAccessStore, useTabbarStore, useUserStore } from '@vben/stores';
import { startProgress, stopProgress } from '@vben/utils';

import { getApiEndpoint } from '#/api';
import { accessRoutes, coreRouteNames } from '#/router/routes';
import {
  HOME_PATHS,
  LOGIN_PATHS,
  TokenStorage,
  useMultiAuthStore,
  usePublicConfigStore,
} from '#/store';

import { generateAccess } from './access';

/** 根据路由路径获取对应端的登录路径 */
function getLoginPathByRoute(path: string): string {
  const endpoint = getApiEndpoint(path);
  return LOGIN_PATHS[endpoint];
}

/** 根据路由路径获取对应端的首页路径 */
function getHomePathByRoute(path: string): string {
  const endpoint = getApiEndpoint(path);
  return HOME_PATHS[endpoint];
}

/** 判断是否是登录页面 */
function isLoginPath(path: string): boolean {
  return Object.values(LOGIN_PATHS).includes(path);
}

/**
 * 通用守卫配置
 * @param router
 */
function setupCommonGuard(router: Router) {
  // 记录已经加载的页面
  const loadedPaths = new Set<string>();

  router.beforeEach((to) => {
    to.meta.loaded = loadedPaths.has(to.path);

    // 页面加载进度条
    if (!to.meta.loaded && preferences.transition.progress) {
      startProgress();
    }
    return true;
  });

  router.afterEach((to) => {
    // 记录页面是否加载,如果已经加载，后续的页面切换动画等效果不在重复执行

    loadedPaths.add(to.path);

    // 关闭页面加载进度条
    if (preferences.transition.progress) {
      stopProgress();
    }
  });
}

// 记录上一次的端类型，用于检测端切换
let lastEndpoint: ApiEndpoint | null = null;

/**
 * 权限访问守卫配置
 * @param router
 */
function setupAccessGuard(router: Router) {
  router.beforeEach(async (to, from) => {
    const accessStore = useAccessStore();
    const userStore = useUserStore();
    const multiAuthStore = useMultiAuthStore();
    const publicConfigStore = usePublicConfigStore();

    // 获取当前路由对应的端类型、登录路径和首页路径
    const currentEndpoint: ApiEndpoint = getApiEndpoint(to.path);
    const currentLoginPath = getLoginPathByRoute(to.path);
    const currentHomePath = getHomePathByRoute(to.path);

    // 首次访问时加载对应端的公开配置（品牌、验证码等）
    if (currentEndpoint === 'admin') {
      if (!publicConfigStore.platformConfigLoaded) {
        // 平台端：加载平台公开配置
        await publicConfigStore.loadPlatformConfig().catch((error) => {
          console.warn('[Router Guard] 加载平台公开配置失败:', error);
        });
      } else if (publicConfigStore.platformConfig?.brand) {
        // 如果已加载，确保应用当前端的品牌配置（处理端切换时的缓存问题）
        publicConfigStore.applyBrandConfig(
          publicConfigStore.platformConfig.brand,
        );
      }
    } else if (currentEndpoint === 'tenant') {
      if (!publicConfigStore.tenantConfigLoaded) {
        // 企业端：加载企业公开配置
        await publicConfigStore.loadTenantConfig().catch((error) => {
          console.warn('[Router Guard] 加载企业公开配置失败:', error);
        });
      } else if (publicConfigStore.tenantConfig?.brand) {
        // 如果已加载，确保应用当前端的品牌配置（处理端切换时的缓存问题）
        publicConfigStore.applyBrandConfig(
          publicConfigStore.tenantConfig.brand,
        );
      }
    }

    // 维护模式检查：配置加载后检查是否处于维护状态
    // 管理端（/admin/*）始终放行，确保管理员可以登录后台关闭维护模式
    const isMaintenancePage = to.path === '/maintenance';
    const maintenanceEnabled =
      publicConfigStore.platformConfig?.maintenance?.enabled ||
      publicConfigStore.tenantConfig?.maintenance?.enabled;
    const isAdminRoute = currentEndpoint === 'admin';

    if (
      maintenanceEnabled &&
      !isMaintenancePage &&
      !isAdminRoute &&
      !isLoginPath(to.path)
    ) {
      return { path: '/maintenance', replace: true };
    }
    // 维护模式已关闭但用户仍在维护页面，重定向回首页
    if (!maintenanceEnabled && isMaintenancePage) {
      return { path: currentHomePath, replace: true };
    }

    // 检测端切换：如果端类型变化，需要重新生成路由和权限
    if (lastEndpoint && lastEndpoint !== currentEndpoint) {
      accessStore.setIsAccessChecked(false);
      accessStore.setAccessMenus([]);
      accessStore.setAccessRoutes([]);
      // 清除权限码，避免使用旧端的权限
      accessStore.setAccessCodes([]);

      const { resetPluginRoutesReady } =
        await import('#/composables/use-plugin-frontend-init');
      resetPluginRoutesReady(router);
    }
    lastEndpoint = currentEndpoint;

    // 从 TokenStorage 获取当前端的 Token（多端分离存储）
    const currentToken = TokenStorage.getToken(currentEndpoint);

    // 基本路由，这些路由不需要进入权限拦截
    if (coreRouteNames.includes(to.name as string)) {
      // 如果当前端已登录且访问登录页，重定向到对应端的首页
      if (isLoginPath(to.path) && currentToken) {
        return (
          (to.query?.redirect as string) ||
          userStore.userInfo?.homePath ||
          currentHomePath
        );
      }
      return true;
    }

    // Token 检查（使用当前端的 Token）
    if (!currentToken) {
      // 明确声明忽略权限访问权限，则可以访问
      if (to.meta.ignoreAccess) {
        return true;
      }

      // 没有访问权限，跳转到对应端的登录页面
      if (!isLoginPath(to.path)) {
        return {
          path: currentLoginPath,
          query:
            to.fullPath === currentHomePath ? {} : { redirect: to.fullPath },
          replace: true,
        };
      }
      return to;
    }

    // 同步 Token 到 accessStore（兼容 vben 框架组件）
    if (accessStore.accessToken !== currentToken) {
      accessStore.setAccessToken(currentToken);
      const refreshToken = TokenStorage.getRefreshToken(currentEndpoint);
      if (refreshToken) {
        accessStore.setRefreshToken(refreshToken);
      }
    }

    // 是否已经生成过动态路由
    if (accessStore.isAccessChecked) {
      // 插件路由可能还未注册（layout onMounted 异步注册），
      // 如果目标是插件 URL 但路由不存在，在 guard 中同步注册插件路由
      const isPluginPath = /\/(tenant|admin)\/plugins\//.test(to.path);
      if (isPluginPath && to.name === 'FallbackNotFound') {
        const { ensurePluginRoutes } =
          await import('#/composables/use-plugin-frontend-init');
        await ensurePluginRoutes(router, to.path);
        // 路由注册后重新解析
        const resolved = router.resolve(to.fullPath);
        if (resolved.name !== 'FallbackNotFound') {
          return { ...resolved, replace: true };
        }
      }
      return true;
    }

    // 生成路由表
    // 当前登录用户拥有的角色标识列表
    // 注意：必须传入 endpoint 参数，因为 route.path 可能还是旧路由
    let userInfo;
    try {
      userInfo =
        userStore.userInfo ||
        (await multiAuthStore.fetchUserInfo(currentEndpoint));
    } catch (error) {
      // 获取用户信息失败（可能是 Token 过期），清除 Token 并跳转到登录页
      console.error('[Router Guard] 获取用户信息失败:', error);
      TokenStorage.clearToken(currentEndpoint);
      accessStore.setAccessToken(null);
      accessStore.setIsAccessChecked(false);
      return {
        path: currentLoginPath,
        query: { redirect: to.fullPath },
        replace: true,
      };
    }

    const userRoles = userInfo.roles ?? [];

    // 生成菜单和路由（根据端类型获取对应的菜单）
    let accessibleMenus;
    let accessibleRoutes;
    try {
      const result = await generateAccess(
        {
          roles: userRoles,
          router,
          routes: accessRoutes,
        },
        currentEndpoint,
      );
      accessibleMenus = result.accessibleMenus;
      accessibleRoutes = result.accessibleRoutes;
    } catch (error) {
      console.error('[Router Guard] 生成菜单路由失败:', error);
      // 菜单 API 可能返回 401 触发 doReAuthenticate；
      // 此处兜底：清 token 并跳登录，避免死循环
      TokenStorage.clearToken(currentEndpoint);
      accessStore.setAccessToken(null);
      accessStore.setIsAccessChecked(false);
      return {
        path: currentLoginPath,
        query: to.fullPath === currentHomePath ? {} : { redirect: to.fullPath },
        replace: true,
      };
    }

    // 保存菜单信息和路由信息
    accessStore.setAccessMenus(accessibleMenus);
    accessStore.setAccessRoutes(accessibleRoutes);
    accessStore.setIsAccessChecked(true);

    const redirectPath = (from.query.redirect ??
      (to.path === currentHomePath
        ? userInfo.homePath || currentHomePath
        : to.fullPath)) as string;

    // 插件路由在 guard 中同步注册（无感方式，不跳转首页）
    const isPluginRedirect = /\/(tenant|admin)\/plugins\//.test(redirectPath);
    if (isPluginRedirect) {
      try {
        const { ensurePluginRoutes } =
          await import('#/composables/use-plugin-frontend-init');
        await ensurePluginRoutes(router, redirectPath);
      } catch (error) {
        console.warn(
          '[Router Guard] ensurePluginRoutes failed, redirecting to home:',
          error,
        );
        return { path: currentHomePath, replace: true };
      }
    }

    return {
      ...router.resolve(redirectPath),
      replace: true,
    };
  });
}

/**
 * 标签页守卫配置
 * 处理多端标签页隔离
 * @param router
 */
function setupTabbarGuard(router: Router) {
  router.beforeEach(async (to) => {
    const tabbarStore = useTabbarStore();
    const currentEndpoint = getApiEndpoint(to.path);

    // 获取当前不需要显示的标签页（非当前端）
    const tabs = tabbarStore.getTabs;
    const invalidTabs = tabs.filter((tab) => {
      const tabEndpoint = getApiEndpoint(tab.path);
      // 忽略 core 路由（如 login, 404 等），它们可能被视为 'user' 但在各端都可能出现
      // 但实际上 login 页面有明确的端路径 (/admin/login, /tenant/login)
      // 只有 404 或 root 可能是通用的
      // 这里简单判断：如果 tabEndpoint 不等于 currentEndpoint，且不是公共路由，则关闭
      return tabEndpoint !== currentEndpoint;
    });

    // 批量关闭非当前端的标签页
    if (invalidTabs.length > 0) {
      const keys = invalidTabs.map((tab) => tab.key as string).filter(Boolean);
      if (keys.length > 0) {
        await tabbarStore._bulkCloseByKeys(keys);
      }
    }

    return true;
  });
}

/**
 * 项目守卫配置
 * @param router
 */
function createRouterGuard(router: Router) {
  /** 通用 */
  setupCommonGuard(router);
  /** 权限访问 */
  setupAccessGuard(router);
  /** 标签页隔离 */
  setupTabbarGuard(router);
}

export { createRouterGuard };

/**
 * 全局 Socket.IO 连接管理 Store
 *
 * 登录后自动建立 Socket.IO 连接，登出时断开。
 * 提供事件 handler 注册/注销机制，收到事件后分发给已注册 handlers。
 */

import type { SocketIOStatus } from '#/composables/use-socketio';

import { computed, ref, watch } from 'vue';

import { useAppConfig } from '@vben/hooks';

import { defineStore } from 'pinia';

import { getApiEndpoint } from '#/api';
import { useSocketIO } from '#/composables/use-socketio';

import { TokenStorage } from './token-storage';

/** Namespace 映射：API endpoint → Socket.IO namespace */
const NAMESPACE_MAP: Record<string, string> = {
  admin: '/admin',
  tenant: '/tenant',
  user: '/user',
};

export const useSocketIOStore = defineStore('socketio', () => {
  // ============================================================
  // 状态
  // ============================================================

  /** 当前连接状态 */
  const status = ref<SocketIOStatus>('disconnected');

  /** 当前连接的 endpoint */
  const currentEndpoint = ref<string>('');

  /** 已注册的事件 handlers */
  const handlers = new Map<string, Set<(data: unknown) => void>>();

  /** Socket.IO composable 实例（延迟创建） */
  let sioInstance: null | ReturnType<typeof useSocketIO> = null;

  // ============================================================
  // 连接管理
  // ============================================================

  /** 是否已连接 */
  const isConnected = computed(() => status.value === 'connected');

  /**
   * 建立连接
   *
   * @param endpoint - API 端类型 ('admin' | 'tenant' | 'user')
   */
  function connect(endpoint?: string) {
    const ep = endpoint || _detectEndpoint();
    if (!ep) return;

    const token = TokenStorage.getToken(ep as 'admin' | 'tenant' | 'user');
    if (!token) return;

    const ns = NAMESPACE_MAP[ep];
    if (!ns) return;

    // 如果已连接到同一 endpoint，忽略
    if (
      sioInstance &&
      currentEndpoint.value === ep &&
      status.value === 'connected'
    ) {
      return;
    }

    // 断开旧连接（避免 endpoint 切换时 socket 被孤立）
    if (sioInstance) {
      sioInstance.disconnect();
      sioInstance = null;
    }

    currentEndpoint.value = ep;

    // 创建新连接（使用后端 API URL，开发环境不能用 window.location.origin）
    const { apiURL } = useAppConfig(import.meta.env, import.meta.env.PROD);
    // 使用 getter 函数实时读取 TokenStorage，确保 token 刷新后 Socket.IO 能获取最新值
    const tokenGetter = () =>
      TokenStorage.getToken(ep as 'admin' | 'tenant' | 'user') || '';
    sioInstance = useSocketIO({
      namespace: ns,
      token: tokenGetter,
      serverUrl: apiURL,
      autoConnect: true,
    });

    // 同步 status
    watch(
      sioInstance.status,
      (newStatus) => {
        status.value = newStatus;
      },
      { immediate: true },
    );

    // 绑定所有已注册的 handlers
    _bindHandlers();
  }

  /**
   * 断开连接
   *
   * 注意：不清 handlers map，保留已注册的 handler，以便重新 connect() 时
   * _bindHandlers() 能自动回绑，避免断线重连后收不到 Socket.IO 事件。
   * 明确登出时需调用 $reset()（会同时清 handlers）。
   */
  function disconnect() {
    if (sioInstance) {
      sioInstance.disconnect();
      sioInstance = null;
    }
    currentEndpoint.value = '';
    status.value = 'disconnected';
  }

  // ============================================================
  // 事件分发
  // ============================================================

  /**
   * 注册事件 handler
   *
   * @param event - 事件名（如 'notification'、'presence:online'）
   * @param handler - 回调函数
   */
  function registerHandler(event: string, handler: (data: unknown) => void) {
    if (!handlers.has(event)) {
      handlers.set(event, new Set());
    }
    handlers.get(event)!.add(handler);

    // 如果已有连接，立即绑定
    if (sioInstance) {
      sioInstance.on(event, handler);
    }
  }

  /**
   * 注销事件 handler
   *
   * @param event - 事件名
   * @param handler - 要移除的回调（不传则移除该事件所有 handler）
   */
  function unregisterHandler(event: string, handler?: (data: unknown) => void) {
    const eventHandlers = handlers.get(event);
    if (!eventHandlers) return;

    if (handler) {
      eventHandlers.delete(handler);
      if (sioInstance) {
        sioInstance.off(event, handler as (...args: unknown[]) => void);
      }
      if (eventHandlers.size === 0) {
        handlers.delete(event);
      }
    } else {
      // 移除该事件所有 handlers
      if (sioInstance) {
        sioInstance.off(event);
      }
      handlers.delete(event);
    }
  }

  /**
   * 发送事件
   */
  function emit(event: string, data?: unknown) {
    sioInstance?.emit(event, data);
  }

  // ============================================================
  // 内部方法
  // ============================================================

  /** 将所有已注册 handlers 绑定到当前 socket（先 off 防止重复注册） */
  function _bindHandlers() {
    if (!sioInstance) return;
    for (const [event, eventHandlers] of handlers) {
      for (const handler of eventHandlers) {
        sioInstance.off(event, handler as (...args: unknown[]) => void);
        sioInstance.on(event, handler);
      }
    }
  }

  /** 检测当前端类型 */
  function _detectEndpoint(): string {
    try {
      const path = window.location.hash
        ? window.location.hash.slice(1)
        : window.location.pathname;
      return getApiEndpoint(path);
    } catch {
      return 'admin';
    }
  }

  /**
   * 完全重置（登出时调用）
   * 断开连接 + 清空 handlers map（防止重登录后重复注册）
   */
  function $reset() {
    if (sioInstance) {
      sioInstance.disconnect();
      sioInstance = null;
    }
    handlers.clear();
    currentEndpoint.value = '';
    status.value = 'disconnected';
  }

  return {
    status,
    currentEndpoint,
    isConnected,
    connect,
    disconnect,
    registerHandler,
    unregisterHandler,
    emit,
    $reset,
  };
});

/**
 * 通用文件下载工具
 * 支持多种文件类型下载：xlsx, csv, 图片, txt, log 等
 */

/** 文件类型映射 */
const MIME_TYPES: Record<string, string> = {
  // 文本类型
  txt: 'text/plain',
  log: 'text/plain',
  json: 'application/json',
  csv: 'text/csv',
  xml: 'application/xml',
  html: 'text/html',
  md: 'text/markdown',

  // 表格类型
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  xls: 'application/vnd.ms-excel',

  // 图片类型
  png: 'image/png',
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
  gif: 'image/gif',
  svg: 'image/svg+xml',
  webp: 'image/webp',
  bmp: 'image/bmp',
  ico: 'image/x-icon',

  // 文档类型
  pdf: 'application/pdf',
  doc: 'application/msword',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  ppt: 'application/vnd.ms-powerpoint',
  pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',

  // 压缩包
  zip: 'application/zip',
  rar: 'application/x-rar-compressed',
  tar: 'application/x-tar',
  gz: 'application/gzip',

  // 二进制
  bin: 'application/octet-stream',
};

/** 下载配置 */
export interface DownloadOptions {
  /** 文件名（含扩展名） */
  filename: string;
  /** 文件类型（可选，会根据文件名自动推断） */
  mimeType?: string;
}

/**
 * 从文件名获取 MIME 类型
 */
function getMimeType(filename: string, customMimeType?: string): string {
  if (customMimeType) return customMimeType;

  const ext = filename.split('.').pop()?.toLowerCase() || '';
  return MIME_TYPES[ext] || 'application/octet-stream';
}

/**
 * 下载 Blob 对象
 * @param blob Blob 对象
 * @param options 下载配置
 */
export function downloadBlob(blob: Blob, options: DownloadOptions): void {
  const { filename, mimeType } = options;
  const finalMimeType = getMimeType(filename, mimeType);

  // 创建带正确 MIME 类型的 Blob
  const finalBlob =
    blob.type === finalMimeType
      ? blob
      : new Blob([blob], { type: finalMimeType });

  const url = URL.createObjectURL(finalBlob);

  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  link.style.display = 'none';

  document.body.append(link);
  link.click();
  link.remove();

  // 释放 URL 对象
  setTimeout(() => URL.revokeObjectURL(url), 100);
}

/**
 * 下载文本内容
 * @param content 文本内容
 * @param options 下载配置
 */
export function downloadText(content: string, options: DownloadOptions): void {
  const { filename, mimeType } = options;
  const finalMimeType = getMimeType(filename, mimeType);

  const blob = new Blob([content], { type: `${finalMimeType};charset=utf-8` });
  downloadBlob(blob, { filename, mimeType: finalMimeType });
}

/**
 * 下载 JSON 数据
 * @param data JSON 数据
 * @param filename 文件名
 * @param pretty 是否格式化（默认 true）
 */
export function downloadJson(
  data: unknown,
  filename: string,
  pretty = true,
): void {
  const content = pretty ? JSON.stringify(data, null, 2) : JSON.stringify(data);
  downloadText(content, { filename, mimeType: 'application/json' });
}

/**
 * 下载 CSV 数据
 * @param data 二维数组或对象数组
 * @param filename 文件名
 * @param headers 表头（当 data 为对象数组时可选，会自动从第一行取 key）
 */
export function downloadCsv(
  data: Record<string, unknown>[] | unknown[][],
  filename: string,
  headers?: string[],
): void {
  let csvContent = '';

  if (data.length === 0) {
    csvContent = '';
  } else if (Array.isArray(data[0])) {
    // 二维数组
    csvContent = (data as unknown[][])
      .map((row) => row.map((cell) => escapeCsvCell(cell)).join(','))
      .join('\n');
  } else {
    // 对象数组
    const objData = data as Record<string, unknown>[];
    const keys = headers || Object.keys(objData[0] || {});

    // 表头
    csvContent = `${keys.map((key) => escapeCsvCell(key)).join(',')}\n`;

    // 数据行
    csvContent += objData
      .map((row) => keys.map((key) => escapeCsvCell(row[key])).join(','))
      .join('\n');
  }

  // 添加 BOM 以支持 Excel 正确显示中文
  const bom = '\uFEFF';
  downloadText(bom + csvContent, { filename, mimeType: 'text/csv' });
}

/**
 * CSV 单元格转义
 */
function escapeCsvCell(value: unknown): string {
  if (value === null || value === undefined) return '';

  const str = String(value);

  // 如果包含逗号、双引号或换行，需要用双引号包裹并转义内部双引号
  if (str.includes(',') || str.includes('"') || str.includes('\n')) {
    return `"${str.replaceAll('"', '""')}"`;
  }

  return str;
}

/**
 * 下载 Base64 编码的文件
 * @param base64 Base64 编码字符串（可带或不带 data URL 前缀）
 * @param options 下载配置
 */
export function downloadBase64(base64: string, options: DownloadOptions): void {
  // 移除 data URL 前缀（如果有）
  const base64Data = base64.includes(',')
    ? (base64.split(',')[1] ?? base64)
    : base64;

  const { filename, mimeType } = options;
  const finalMimeType = getMimeType(filename, mimeType);

  // 解码 Base64
  const binaryString = atob(base64Data);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }

  const blob = new Blob([bytes], { type: finalMimeType });
  downloadBlob(blob, { filename, mimeType: finalMimeType });
}

/**
 * 下载 ArrayBuffer
 * @param buffer ArrayBuffer 数据
 * @param options 下载配置
 */
export function downloadArrayBuffer(
  buffer: ArrayBuffer,
  options: DownloadOptions,
): void {
  const { filename, mimeType } = options;
  const finalMimeType = getMimeType(filename, mimeType);

  const blob = new Blob([buffer], { type: finalMimeType });
  downloadBlob(blob, { filename, mimeType: finalMimeType });
}

/**
 * 通用下载函数
 * 根据数据类型自动选择下载方法
 *
 * @param data 数据（支持 string, Blob, ArrayBuffer, Base64, 对象/数组）
 * @param options 下载配置
 */
export function download(
  data: ArrayBuffer | Blob | Record<string, unknown>[] | string | unknown[][],
  options: DownloadOptions,
): void {
  const { filename } = options;
  const ext = filename.split('.').pop()?.toLowerCase();

  if (data instanceof Blob) {
    downloadBlob(data, options);
  } else if (data instanceof ArrayBuffer) {
    downloadArrayBuffer(data, options);
  } else if (typeof data === 'string') {
    // 检查是否为 Base64
    if (
      data.startsWith('data:') ||
      /^[A-Z0-9+/=]+$/i.test(data.slice(0, 100))
    ) {
      downloadBase64(data, options);
    } else {
      downloadText(data, options);
    }
  } else if (Array.isArray(data)) {
    // 数组数据
    if (ext === 'csv') {
      downloadCsv(data, filename);
    } else if (ext === 'json') {
      downloadJson(data, filename);
    } else {
      // 默认转为 JSON
      downloadJson(data, filename);
    }
  } else {
    // 其他对象转为 JSON
    downloadJson(data, filename);
  }
}

/**
 * 插件前端动态加载工具
 *
 * 仅通过注入模式加载：
 *   - 运行时插件（生产/开发）→ 通过 <script> 标签加载 UMD 包
 *
 * 设计约束：
 *   - 不将 backend/plugins 源码编译进宿主前端 bundle
 *   - 插件必须保持独立构建与独立发布
 */

/** 已加载的插件缓存 */
const loadedPlugins: Map<string, Record<string, unknown>> = new Map();

/** 加载中的 Promise 缓存（防止重复加载） */
const loadingPromises: Map<
  string,
  Promise<Record<string, unknown>>
> = new Map();
/** CSS 解析中的 Promise 缓存（防止重复探测） */
const cssLoadingPromises: Map<string, Promise<void>> = new Map();

/**
 * 将插件名转为全局变量名: crm-module → NovusPlugin_crm_module
 */
function toGlobalVarName(pluginName: string): string {
  return `NovusPlugin_${pluginName.replaceAll('-', '_')}`;
}

function _injectPluginCSS(pluginName: string, cssFileName: string): void {
  const cssId = `novus-plugin-css-${pluginName}`;
  if (document.getElementById(cssId)) return;

  const link = document.createElement('link');
  link.id = cssId;
  link.rel = 'stylesheet';
  link.href = `/plugin-assets/${pluginName}/${cssFileName}`;
  document.head.append(link);
}

/**
 * 探测插件 CSS 文件名并按需加载。
 *
 * 历史插件存在两种命名：
 * - {pluginName}.css（规范命名）
 * - style.css（Vite 默认库模式产物）
 *
 * 若都不存在，则跳过，不阻塞 JS 入口加载。
 */
async function loadPluginCSS(pluginName: string): Promise<void> {
  const cssId = `novus-plugin-css-${pluginName}`;
  if (document.getElementById(cssId)) return;

  const pending = cssLoadingPromises.get(pluginName);
  if (pending) return pending;

  const task = (async () => {
    const candidates = [`${pluginName}.css`, 'style.css'];
    for (const candidate of candidates) {
      const url = `/plugin-assets/${pluginName}/${candidate}`;
      try {
        const resp = await fetch(url, { method: 'HEAD', cache: 'no-cache' });
        if (resp.ok) {
          _injectPluginCSS(pluginName, candidate);
          return;
        }
      } catch {
        // 静默：不因 CSS 探测失败影响插件 JS 组件加载
      }
    }
  })();

  cssLoadingPromises.set(pluginName, task);
  try {
    await task;
  } finally {
    cssLoadingPromises.delete(pluginName);
  }
}

/**
 * 动态加载插件 UMD JS 包（+ CSS）
 *
 * @param pluginName 插件名（kebab-case）
 * @returns 插件导出的模块对象
 */
export async function loadPluginComponents(
  pluginName: string,
): Promise<Record<string, unknown>> {
  // 已缓存
  const cached = loadedPlugins.get(pluginName);
  if (cached) return cached;

  // 正在加载中
  const existing = loadingPromises.get(pluginName);
  if (existing) return existing;

  const promise = (async (): Promise<Record<string, unknown>> => {
    // 先记录 loadingPromise，再进行 await，避免并发窗口重复注入 script
    await loadPluginCSS(pluginName);

    return new Promise<Record<string, unknown>>((resolve, reject) => {
      const cacheBust = import.meta.env.DEV ? `?t=${Date.now()}` : '';
      const scriptUrl = `/plugin-assets/${pluginName}/index.js${cacheBust}`;
      const script = document.createElement('script');
      script.src = scriptUrl;
      script.async = true;

      script.addEventListener('load', () => {
        const globalVar = toGlobalVarName(pluginName);
        const mod = (window as unknown as Record<string, unknown>)[
          globalVar
        ] as Record<string, unknown> | undefined;

        if (mod) {
          // 调用插件 setup() 注册 i18n 等
          if (typeof mod.setup === 'function') {
            try {
              (mod.setup as () => void)();
            } catch (error) {
              console.error(
                `[PluginLoader] setup() failed for '${pluginName}':`,
                error,
              );
            }
          }
          loadedPlugins.set(pluginName, mod);
          resolve(mod);
          return;
        }
        reject(
          new Error(
            `Plugin '${pluginName}' loaded but window.${globalVar} not found`,
          ),
        );
      });

      script.addEventListener('error', () => {
        reject(new Error(`Failed to load plugin script: ${scriptUrl}`));
      });

      document.head.append(script);
    });
  })();

  loadingPromises.set(pluginName, promise);
  try {
    return await promise;
  } finally {
    loadingPromises.delete(pluginName);
  }
}

/**
 * 获取插件导出的单个组件
 *
 * @param pluginName 插件名
 * @param componentName 组件名（插件模块的导出 key）
 */
export async function getPluginComponent(
  pluginName: string,
  componentName: string,
): Promise<null | unknown> {
  try {
    const mod = await loadPluginComponents(pluginName);
    return mod[componentName] ?? null;
  } catch {
    console.error(
      `Failed to get component '${componentName}' from plugin '${pluginName}'`,
    );
    return null;
  }
}

/**
 * 检查插件是否已加载
 */
export function isPluginLoaded(pluginName: string): boolean {
  return loadedPlugins.has(pluginName);
}

/**
 * 卸载插件（清除缓存 + 移除 script 标签）
 */
export function unloadPlugin(pluginName: string): void {
  loadedPlugins.delete(pluginName);
  loadingPromises.delete(pluginName);
  // 移除 script 标签 + 清除全局变量
  const scripts = document.querySelectorAll(
    `script[src*="/plugin-assets/${pluginName}/"]`,
  );
  for (const s of scripts) {
    s.remove();
  }
  const globalVar = toGlobalVarName(pluginName);
  delete (window as unknown as Record<string, unknown>)[globalVar];

  // 移除 CSS
  const css = document.getElementById(`novus-plugin-css-${pluginName}`);
  if (css) css.remove();
}

/**
 * 插件共享依赖暴露
 *
 * 将插件常用的宿主依赖挂载到 window，供插件 UMD 包作为 external 引用。
 * 必须在 bootstrap 早期调用 exposePluginShared()。
 *
 * 插件 vite.config 中 rollupOptions.external 映射:
 *   'vue'                -> window.Vue
 *   'vue-router'         -> window.VueRouter
 *   'ant-design-vue'     -> window.AntDesignVue
 *   '@novus/plugin-shared' -> window.NovusPluginShared
 */

import * as Vue from 'vue';
import * as VueRouter from 'vue-router';

import { IconifyIcon } from '@vben/icons';
import { i18n } from '@vben/locales';
import { useUserStore } from '@vben/stores';

import * as AntDesignVue from 'ant-design-vue';

import { $t } from '#/locales';
import { getCurrentEndpoint } from '#/router/access';
import { TokenStorage } from '#/store/shared/token-storage';
import { usePluginExtensionsStore } from '#/stores/plugin-extensions';
import { usePluginSlotsStore } from '#/stores/plugin-slots';
import { requestClient } from '#/utils/request';

// Re-export for dev mode: plugins import { $t, IconifyIcon, ... } from '@novus/plugin-shared'
export {
  $t,
  getAuthToken,
  getCurrentUser,
  IconifyIcon,
  requestClient,
  usePluginExtensionsStore,
  usePluginSlotsStore,
};

/**
 * 获取当前端（admin/tenant/user）的 JWT Access Token
 * 供插件 Socket.IO 等非 HTTP 通道鉴权使用
 */
function getAuthToken(): null | string {
  const endpoint = getCurrentEndpoint();
  return TokenStorage.getToken(endpoint);
}

/**
 * 获取当前登录用户信息（供插件协作、评论等场景使用）
 */
function getCurrentUser(): {
  id: null | number;
  name: string;
  username: string;
} {
  try {
    const userStore = useUserStore();
    const info = userStore.userInfo;
    if (info) {
      return {
        id: info.userId ? Number(info.userId) : null,
        username: info.username || '',
        name: info.realName || info.username || '',
      };
    }
  } catch {
    /* store not ready */
  }
  return { id: null, username: '', name: '' };
}

export interface NovusPluginSharedAPI {
  /** HTTP 请求客户端 */
  requestClient: typeof requestClient;
  /** i18n 翻译函数 */
  $t: typeof $t;
  /** 图标组件 */
  IconifyIcon: typeof IconifyIcon;
  /** 插件槽位 Store（UI 插槽：headerWidgets / floatingPanels 等） */
  usePluginSlotsStore: typeof usePluginSlotsStore;
  /** 插件扩展 Store（编辑器扩展 / 面板 / 命令） */
  usePluginExtensionsStore: typeof usePluginExtensionsStore;
  /** 注册插件国际化消息 */
  registerLocale: (
    locale: string,
    prefix: string,
    messages: Record<string, unknown>,
  ) => void;
  /** 获取当前端 JWT Access Token（供 Socket.IO 等非 HTTP 通道鉴权） */
  getAuthToken: () => null | string;
  /** 获取当前登录用户信息（供协作、评论等场景） */
  getCurrentUser: () => { id: null | number; name: string; username: string };
}

/**
 * 将共享依赖挂载到 window（调用一次即可）
 */
export function exposePluginShared(): void {
  const w = window as unknown as Record<string, unknown>;

  // Vue 核心
  w.Vue = Vue;

  // Vue Router
  w.VueRouter = VueRouter;

  // Ant Design Vue
  w.AntDesignVue = AntDesignVue;

  // NovusAI 插件共享 API
  w.NovusPluginShared = {
    requestClient,
    $t,
    IconifyIcon,
    usePluginSlotsStore,
    usePluginExtensionsStore,
    registerLocale: _registerPluginLocale,
    getAuthToken,
    getCurrentUser,
  } satisfies NovusPluginSharedAPI;
}

/**
 * 将插件提供的翻译消息合并到全局 i18n 实例
 */
function _registerPluginLocale(
  locale: string,
  prefix: string,
  messages: Record<string, unknown>,
): void {
  try {
    if (i18n?.global) {
      // 将扁平点分 key（如 'folder.all': '全部文档'）转为嵌套对象
      // 再包裹 prefix（如 "plugin.novusdoc"）→ { plugin: { novusdoc: { folder: { all: '全部文档' } } } }
      const nestedMessages: Record<string, unknown> = {};
      for (const [key, value] of Object.entries(messages)) {
        const keyParts = key.split('.');
        let current: Record<string, unknown> = nestedMessages;
        for (let i = 0; i < keyParts.length - 1; i++) {
          if (
            !(keyParts[i]! in current) ||
            typeof current[keyParts[i]!] !== 'object'
          ) {
            current[keyParts[i]!] = {};
          }
          current = current[keyParts[i]!] as Record<string, unknown>;
        }
        current[keyParts[keyParts.length - 1]!] = value;
      }

      // 包裹 prefix 路径
      const prefixParts = prefix.split('.');
      let wrapped: Record<string, unknown> = nestedMessages;
      for (let i = prefixParts.length - 1; i >= 0; i--) {
        wrapped = { [prefixParts[i]!]: wrapped };
      }
      i18n.global.mergeLocaleMessage(locale, wrapped);
    }
  } catch {
    console.error('[PluginShared] Failed to register plugin locale');
  }
}

/**
 * 请求/响应拦截器
 *
 * 包含：
 * - 请求拦截器：Token 自动携带、重复请求取消、Loading 管理
 * - 响应拦截器：数据格式解析、业务错误处理、Token 刷新、HTTP 错误提示
 *
 * @module utils/request/interceptors
 */
import type { AxiosResponse, InternalAxiosRequestConfig } from 'axios';

import type { RequestClient } from './request-client';
import type { ApiEndpoint, RequestOptions } from './types';

import axios from 'axios';

import { isAuthError } from './error-codes';

// ============================================================
// 类型定义
// ============================================================

/** 扩展的请求配置（包含选项） */
interface ExtendedConfig extends InternalAxiosRequestConfig {
  __options?: RequestOptions;
  __isRetryRequest?: boolean;
  __loadingKey?: string;
}

// ============================================================
// Loading 管理
// ============================================================

/** Loading 实例管理 */
const loadingState = {
  count: 0,
  hideLoading: null as (() => void) | null,
};

/** Token 获取器 */
export interface TokenGetter {
  getToken: (endpoint: ApiEndpoint) => null | string;
  getRefreshToken: (endpoint: ApiEndpoint) => null | string;
}

/** 认证处理器 */
export interface AuthHandler {
  doRefreshToken: () => Promise<string>;
  doReAuthenticate: () => Promise<void>;
}

/** 消息处理器 */
export interface MessageHandler {
  showMessage: (type: 'error' | 'success', message: string) => void;
  showLoading: (message?: string) => () => void;
  t: (key: string) => string;
}

// ============================================================
// 工具函数
// ============================================================

/**
 * 根据请求 URL 判断端类型
 */
export function getEndpointByUrl(url: string): ApiEndpoint {
  if (url.startsWith('/admin')) return 'admin';
  if (url.startsWith('/tenant')) return 'tenant';
  // 双端插件路由：/plugins/{name}/admin/* 或 /plugins/{name}/tenant/*
  if (url.startsWith('/plugins/')) {
    if (/^\/plugins\/[^/]+\/admin(\/|$)/.test(url)) return 'admin';
    if (/^\/plugins\/[^/]+\/tenant(\/|$)/.test(url)) return 'tenant';
  }
  return 'user';
}

/**
 * 根据路径获取端类型
 */
export function getEndpointByPath(path: string): ApiEndpoint {
  if (path.startsWith('/admin')) return 'admin';
  if (path.startsWith('/tenant')) return 'tenant';
  return 'user';
}

/**
 * 格式化 Token
 */
function formatToken(token: null | string): null | string {
  return token ? `Bearer ${token}` : null;
}

// ============================================================
// 请求拦截器
// ============================================================

/**
 * 创建请求拦截器
 */
export function createRequestInterceptor(
  client: RequestClient,
  tokenGetter: TokenGetter,
  getLocale: () => string,
  messageHandler: MessageHandler,
) {
  return {
    fulfilled: async (config: ExtendedConfig) => {
      const options = config?.__options || {};

      // 1. 重复请求取消
      if (options.cancelDuplicateRequest !== false) {
        client.removePending(config);
        client.addPending(config);
      }

      // 2. 自动携带 Token（根据 URL 判断端类型）
      const requestUrl = config.url || '';
      const endpoint = getEndpointByUrl(requestUrl);
      const token = tokenGetter.getToken(endpoint);
      if (token) {
        config.headers.Authorization = formatToken(token);
      }

      // 3. Accept-Language
      config.headers['Accept-Language'] = getLocale();

      // 4. Loading 管理
      if (options.loading) {
        loadingState.count++;
        if (loadingState.count === 1) {
          loadingState.hideLoading = messageHandler.showLoading(
            messageHandler.t('common.http.loading'),
          );
        }
      }

      return config;
    },
    rejected: (error: any) => Promise.reject(error),
  };
}

/**
 * 关闭 Loading
 */
function closeLoading() {
  if (loadingState.count > 0) {
    loadingState.count--;
  }
  if (loadingState.count === 0 && loadingState.hideLoading) {
    loadingState.hideLoading();
    loadingState.hideLoading = null;
  }
}

/**
 * 创建 Loading 响应拦截器
 * 请求完成后关闭 Loading 并清理 pending
 */
export function createLoadingInterceptor(client: RequestClient) {
  return {
    fulfilled: (response: AxiosResponse) => {
      const config = response.config as ExtendedConfig;
      const options = config?.__options || {};

      // 清理 pending 请求
      client.removePending(config);

      if (options.loading) {
        closeLoading();
      }
      return response;
    },
    rejected: (error: any) => {
      const config = error.config as ExtendedConfig;
      const options = config?.__options || {};

      // 清理 pending 请求（即使失败也要清理）
      if (config) {
        client.removePending(config);
      }

      if (options?.loading) {
        closeLoading();
      }
      return Promise.reject(error);
    },
  };
}

// ============================================================
// 响应拦截器 - 数据格式解析
// ============================================================

/**
 * 创建响应数据拦截器
 * 处理 raw/body/data 三种返回模式
 */
export function createResponseDataInterceptor(
  successCode: number = 0,
  codeField: string = 'code',
  dataField: string = 'data',
) {
  return {
    fulfilled: (response: AxiosResponse) => {
      const config = response.config as ExtendedConfig;
      const options = config?.__options || {};
      const { data: responseData, status } = response;

      // raw 模式：返回原始 AxiosResponse
      if (options.responseReturn === 'raw') {
        return response;
      }

      // HTTP 状态码检查
      if (status >= 200 && status < 400) {
        // body 模式：返回响应体
        if (options.responseReturn === 'body') {
          return responseData;
        }

        // data 模式：检查业务 code 并解构 data 字段
        const code = responseData?.[codeField];
        if (code === successCode) {
          return responseData[dataField];
        }
      }

      // 业务错误，抛出供后续拦截器处理
      throw Object.assign({}, response, { response });
    },
  };
}

// ============================================================
// 响应拦截器 - Token 刷新
// ============================================================

/**
 * 创建 Token 刷新拦截器
 *
 * 认证错误判断逻辑（基于 API 错误码规范文档）：
 * - HTTP 401 状态码 + 业务错误码 4010/4011/4012
 * - 4010: UNAUTHORIZED - 未认证
 * - 4011: TOKEN_EXPIRED - 令牌已过期
 * - 4012: TOKEN_INVALID - 无效的令牌
 */
/** 登录接口路径（这些接口的 401 不应触发重新认证） */
const LOGIN_URLS = [
  '/admin/auth/login',
  '/tenant/auth/login',
  '/api/v1/auth/login',
];

/**
 * 检查是否为登录接口
 */
function isLoginUrl(url: string | undefined): boolean {
  if (!url) return false;
  return LOGIN_URLS.some((loginUrl) => url.includes(loginUrl));
}

export function createAuthInterceptor(
  client: RequestClient,
  _tokenGetter: TokenGetter,
  authHandler: AuthHandler,
  enableRefreshToken: boolean = true,
) {
  return {
    rejected: async (error: any) => {
      // 取消的请求不处理
      if (axios.isCancel(error)) {
        throw error;
      }

      const { config, response } = error;

      // 非 401 HTTP 状态码，继续传递
      if (response?.status !== 401) {
        throw error;
      }

      // 登录接口的 401 不应触发重新认证，应该显示错误消息
      if (isLoginUrl(config?.url)) {
        throw error;
      }

      // 检查业务错误码是否为认证错误 (4010/4011/4012)
      const businessCode = response?.data?.code;
      if (!isAuthError(businessCode)) {
        // 不是认证错误，继续传递给其他拦截器处理
        throw error;
      }

      // 4010 UNAUTHORIZED 或未启用刷新或已是重试请求 -> 直接重新认证
      if (
        businessCode === 4010 ||
        !enableRefreshToken ||
        config?.__isRetryRequest
      ) {
        await authHandler.doReAuthenticate();
        throw error;
      }

      // 4011 TOKEN_EXPIRED 或 4012 TOKEN_INVALID -> 尝试刷新 Token

      // 正在刷新中，加入队列等待
      if (client.isRefreshing) {
        return new Promise((resolve, reject) => {
          client.refreshTokenQueue.push({
            resolve: (newToken: string) => {
              config.headers.Authorization = formatToken(newToken);
              resolve(client.instance.request(config));
            },
            reject: (err: any) => {
              reject(err);
            },
          });
        });
      }

      // 开始刷新
      client.isRefreshing = true;
      config.__isRetryRequest = true;

      try {
        const newToken = await authHandler.doRefreshToken();

        // 刷新成功，处理队列中的请求
        client.refreshTokenQueue.forEach((item) => item.resolve(newToken));
        client.refreshTokenQueue = [];

        // 重试原请求
        config.headers.Authorization = formatToken(newToken);
        return client.instance.request(config);
      } catch (refreshError) {
        // 刷新失败，reject 队列中所有等待的请求
        client.refreshTokenQueue.forEach((item) => item.reject(refreshError));
        client.refreshTokenQueue = [];
        await authHandler.doReAuthenticate();
        throw refreshError;
      } finally {
        client.isRefreshing = false;
      }
    },
  };
}

// ============================================================
// 响应拦截器 - 错误消息
// ============================================================

/**
 * 创建错误消息拦截器
 * 注意：如果响应中有业务错误消息，则不显示 HTTP 错误消息
 */
export function createErrorMessageInterceptor(messageHandler: MessageHandler) {
  return {
    rejected: (error: any) => {
      // 取消的请求不处理
      if (axios.isCancel(error)) {
        return Promise.reject(error);
      }

      const config = error.config as ExtendedConfig;
      const options = config?.__options || {};

      // 网络错误
      const errStr = error?.toString?.() ?? '';
      if (errStr.includes('Network Error')) {
        if (options.showErrorMessage !== false) {
          messageHandler.showMessage(
            'error',
            messageHandler.t('common.http.networkError'),
          );
        }
        return Promise.reject(error);
      }

      // 超时错误
      if (error?.message?.includes?.('timeout')) {
        if (options.showErrorMessage !== false) {
          messageHandler.showMessage(
            'error',
            messageHandler.t('common.http.requestTimeout'),
          );
        }
        return Promise.reject(error);
      }

      // 如果有业务错误消息，跳过 HTTP 错误消息（已由 BusinessErrorInterceptor 处理）
      const responseData = error?.response?.data;
      const hasBusinessMessage =
        responseData?.message || responseData?.error || responseData?.msg;
      if (hasBusinessMessage) {
        return Promise.reject(error);
      }

      // HTTP 状态码错误（仅当没有业务错误消息时显示）
      const status = error?.response?.status;
      if (status && options.showErrorMessage !== false) {
        const statusMessages: Record<number, string> = {
          400: 'common.http.badRequest',
          401: 'common.http.unauthorized',
          403: 'common.http.forbidden',
          404: 'common.http.notFound',
          408: 'common.http.requestTimeout',
          500: 'common.http.internalServerError',
          502: 'common.http.badGateway',
          503: 'common.http.serviceUnavailable',
          504: 'common.http.gatewayTimeout',
        };
        const messageKey =
          statusMessages[status] || 'common.http.internalServerError';
        messageHandler.showMessage('error', messageHandler.t(messageKey));
      }

      return Promise.reject(error);
    },
  };
}

// ============================================================
// 响应拦截器 - 业务错误消息
// ============================================================

/**
 * 创建业务错误消息拦截器
 */
export function createBusinessErrorInterceptor(messageHandler: MessageHandler) {
  return {
    rejected: (error: any) => {
      // 取消的请求不处理
      if (axios.isCancel(error)) {
        return Promise.reject(error);
      }

      const config = error.config as ExtendedConfig;
      const options = config?.__options || {};
      const responseData = error?.response?.data;

      // 显示业务错误消息
      if (options.showCodeMessage !== false && responseData) {
        const errorMessage =
          responseData.message || responseData.error || responseData.msg;
        if (errorMessage) {
          messageHandler.showMessage('error', errorMessage);
        }
      }

      return Promise.reject(error);
    },
  };
}

// ============================================================
// 响应拦截器 - 成功消息
// ============================================================

/**
 * 创建成功消息拦截器
 */
export function createSuccessMessageInterceptor(
  messageHandler: MessageHandler,
  defaultSuccessMessage?: string,
) {
  return {
    fulfilled: (response: AxiosResponse | null | undefined) => {
      // 处理 data 模式下返回 null/undefined 的情况（如 DELETE 接口返回 data: null）
      if (response === null || response === undefined) {
        return response;
      }

      // 如果是解构后的数据（非 AxiosResponse），直接返回
      if (typeof response !== 'object' || !('config' in response)) {
        return response;
      }

      const config = response.config as ExtendedConfig;
      const options = config?.__options || {};

      // 显示成功消息
      if (options.showSuccessMessage) {
        const message =
          options.successMessage ||
          defaultSuccessMessage ||
          messageHandler.t('common.http.operationSuccess');
        messageHandler.showMessage('success', message);
      }

      return response;
    },
  };
}

/**
 * HTTP 请求客户端
 *
 * 基于 axios 封装，支持：
 * - 多端 Token 自动携带
 * - 重复请求取消
 * - Loading 状态管理
 * - 业务错误码处理
 * - Token 自动刷新
 * - 文件上传下载
 * - SSE 流式请求
 *
 * @module utils/request/request-client
 */
import type {
  AxiosInstance,
  AxiosResponse,
  InternalAxiosRequestConfig,
} from 'axios';

import type {
  ApiEndpoint,
  HttpResponse,
  ParamsSerializer,
  RequestClientConfig,
  RequestClientOptions,
  RequestInterceptorConfig,
  RequestOptions,
  ResponseInterceptorConfig,
  SseRequestOptions,
  UploadFileData,
  UploadProgressCallback,
} from './types';

import axios from 'axios';
import qs from 'qs';

// ============================================================
// 默认配置
// ============================================================

/** 默认请求选项 */
const DEFAULT_OPTIONS: Required<RequestOptions> = {
  cancelDuplicateRequest: true,
  loading: false,
  responseReturn: 'data',
  showErrorMessage: true,
  showCodeMessage: true,
  showSuccessMessage: false,
  successMessage: '',
  paramsSerializer: 'brackets',
};

// ============================================================
// 工具函数
// ============================================================

/**
 * 获取参数序列化器
 */
function getParamsSerializer(type: ParamsSerializer) {
  const formatMap: Record<
    ParamsSerializer,
    'brackets' | 'comma' | 'indices' | 'repeat'
  > = {
    brackets: 'brackets',
    comma: 'comma',
    indices: 'indices',
    repeat: 'repeat',
  };
  return (params: any) =>
    qs.stringify(params, { arrayFormat: formatMap[type] });
}

/**
 * 根据请求 URL 判断端类型
 */
function getEndpointByUrl(url: string): ApiEndpoint {
  if (url.startsWith('/admin')) return 'admin';
  if (url.startsWith('/tenant')) return 'tenant';
  // 双端插件路由：/plugins/{name}/admin/* 或 /plugins/{name}/tenant/*
  if (url.startsWith('/plugins/')) {
    if (/^\/plugins\/[^/]+\/admin(\/|$)/.test(url)) return 'admin';
    if (/^\/plugins\/[^/]+\/tenant(\/|$)/.test(url)) return 'tenant';
  }
  return 'user';
}

/**
 * 生成请求唯一标识（用于重复请求判断）
 */
function getPendingKey(config: InternalAxiosRequestConfig): string {
  const { url, method, params, data, headers } = config;
  const dataStr = typeof data === 'string' ? data : JSON.stringify(data);
  return [
    url,
    method,
    JSON.stringify(params),
    dataStr,
    (headers as any)?.Authorization || '',
  ].join('&');
}

// ============================================================
// RequestClient 类
// ============================================================

export class RequestClient {
  /** 重新认证函数（拦截器使用） */
  public doReAuthenticate?: () => Promise<void>;

  /** Token 刷新函数（拦截器使用） */
  public doRefreshToken?: () => Promise<string>;

  /** Refresh Token 获取函数（拦截器使用） */
  public getRefreshToken?: (endpoint: ApiEndpoint) => null | string;

  /** Axios 实例 */
  public readonly instance: AxiosInstance;

  /** 正在刷新 Token */
  public isRefreshing = false;

  /** Token 刷新队列（存储 resolve/reject 回调） */
  public refreshTokenQueue: Array<{
    reject: (error: any) => void;
    resolve: (token: string) => void;
  }> = [];

  /** 显示消息（拦截器使用） */
  public showMessage?: (type: 'error' | 'success', message: string) => void;

  /** 国际化函数（拦截器使用） */
  public t?: (key: string) => string;

  /** 默认选项 */
  private readonly defaultOptions: Required<RequestOptions>;

  /** Token 获取函数 */
  private getToken?: (endpoint: ApiEndpoint) => null | string;

  /** 待处理请求 Map（用于取消重复请求） */
  private pendingMap = new Map<string, AbortController>();

  constructor(options: RequestClientOptions = {}) {
    const { baseURL, timeout = 10_000, headers = {}, ...restOptions } = options;

    // 合并默认选项
    this.defaultOptions = { ...DEFAULT_OPTIONS, ...restOptions };

    // 创建 Axios 实例
    this.instance = axios.create({
      baseURL,
      timeout,
      headers: {
        'Content-Type': 'application/json;charset=utf-8',
        'Cache-Control': 'no-cache',
        Pragma: 'no-cache',
        ...headers,
      },
      paramsSerializer: getParamsSerializer(
        this.defaultOptions.paramsSerializer,
      ),
    });

    // 绑定方法
    this.bindMethods();
  }

  /** 添加待处理请求（拦截器使用） */
  public addPending(config: InternalAxiosRequestConfig) {
    const key = getPendingKey(config);
    if (this.pendingMap.has(key)) {
      // 取消之前的请求
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      const controller = this.pendingMap.get(key)!;
      controller.abort();
      this.pendingMap.delete(key);
    }
    const controller = new AbortController();
    config.signal = controller.signal;
    this.pendingMap.set(key, controller);
  }

  // ============================================================
  // 配置方法
  // ============================================================

  /** 添加请求拦截器 */
  addRequestInterceptor(config: RequestInterceptorConfig) {
    this.instance.interceptors.request.use(
      config.fulfilled as any,
      config.rejected,
    );
    return this;
  }

  /** 添加响应拦截器 */
  addResponseInterceptor(config: ResponseInterceptorConfig) {
    this.instance.interceptors.response.use(
      config.fulfilled as any,
      config.rejected,
    );
    return this;
  }

  /** DELETE 请求 */
  delete<T = any>(url: string, config?: RequestClientConfig): Promise<T> {
    return this.request<T>(url, { ...config, method: 'DELETE' });
  }

  /**
   * 文件下载
   * @param url 下载 URL
   * @param config 请求配置
   */
  async download<T = Blob>(
    url: string,
    config?: RequestClientConfig & { data?: any; method?: 'GET' | 'POST' },
  ): Promise<T> {
    const { method = 'GET', data, ...restConfig } = config || {};

    try {
      const response = await this.instance.request<T>({
        url,
        method,
        data,
        responseType: 'blob',
        ...restConfig,
        // 下载请求不显示错误消息（由调用方处理）
        ...({
          __options: { showErrorMessage: false, showCodeMessage: false },
        } as any),
      });

      // 检查响应是否为错误（某些后端返回 JSON 错误而不是 Blob）
      const blob = response.data as Blob;
      if (blob.type === 'application/json') {
        // 解析 JSON 错误
        const text = await blob.text();
        const errorData = JSON.parse(text);
        throw new Error(
          errorData.message || errorData.error || 'Download failed',
        );
      }

      return response.data;
    } catch (error: any) {
      // 显示友好的错误提示
      if (this.showMessage) {
        const message =
          error?.message ||
          this.t?.('common.http.downloadFailed') ||
          'Download failed';
        this.showMessage('error', message);
      }
      throw error;
    }
  }

  /** GET 请求 */
  get<T = any>(url: string, config?: RequestClientConfig): Promise<T> {
    return this.request<T>(url, { ...config, method: 'GET' });
  }

  /** 获取基础 URL */
  getBaseUrl(): string | undefined {
    return this.instance.defaults.baseURL;
  }

  // ============================================================
  // 拦截器方法
  // ============================================================

  /** PATCH 请求 */
  patch<T = any>(
    url: string,
    data?: any,
    config?: RequestClientConfig,
  ): Promise<T> {
    return this.request<T>(url, { ...config, data, method: 'PATCH' });
  }

  /** POST 请求 */
  post<T = any>(
    url: string,
    data?: any,
    config?: RequestClientConfig,
  ): Promise<T> {
    return this.request<T>(url, { ...config, data, method: 'POST' });
  }

  // ============================================================
  // 重复请求取消
  // ============================================================

  /**
   * SSE POST 请求
   */
  async postSSE(url: string, data?: any, options?: SseRequestOptions) {
    return this.requestSSE(url, data, { ...options, method: 'POST' });
  }

  /** PUT 请求 */
  put<T = any>(
    url: string,
    data?: any,
    config?: RequestClientConfig,
  ): Promise<T> {
    return this.request<T>(url, { ...config, data, method: 'PUT' });
  }

  // ============================================================
  // HTTP 方法
  // ============================================================

  /** 移除待处理请求（拦截器使用） */
  public removePending(config: InternalAxiosRequestConfig) {
    const key = getPendingKey(config);
    this.pendingMap.delete(key);
  }

  /**
   * 通用请求方法
   * Loading 由拦截器统一管理
   */
  async request<T = any>(
    url: string,
    config: RequestClientConfig = {},
  ): Promise<T> {
    // 合并选项
    const options: Required<RequestOptions> = {
      ...this.defaultOptions,
      ...config,
    };

    const response = await this.instance.request<
      T,
      AxiosResponse<HttpResponse<T>>
    >({
      url,
      ...config,
      // 存储选项到 config 中，供拦截器使用
      ...({ __options: options } as any),
    });

    return response as unknown as T;
  }

  /**
   * SSE 请求
   * @param url 请求 URL
   * @param data 请求数据
   * @param options SSE 选项，包含 onMessage/onEnd/onError/abortController
   */
  async requestSSE(url: string, data?: any, options?: SseRequestOptions) {
    const { onMessage, onEnd, onError, abortController, ...fetchOptions } =
      options || {};

    try {
      const baseUrl = this.instance.defaults.baseURL || '';
      const fullUrl = baseUrl
        ? `${baseUrl.replace(/\/+$/, '')}/${url.replace(/^\/+/, '')}`
        : url;

      // 构建请求头
      const headers = new Headers();
      headers.set('Accept', 'text/event-stream');
      headers.set('Content-Type', 'application/json');

      // 添加 Token
      if (this.getToken) {
        const endpoint = getEndpointByUrl(url);
        const token = this.getToken(endpoint);
        if (token) {
          headers.set('Authorization', `Bearer ${token}`);
        }
      }

      // 合并自定义 headers
      if (fetchOptions?.headers) {
        new Headers(fetchOptions.headers).forEach((v, k) => headers.set(k, v));
      }

      // 准备请求体
      let body: BodyInit | null = null;
      if (data && fetchOptions?.method !== 'GET') {
        body = typeof data === 'string' ? data : JSON.stringify(data);
      }

      const response = await fetch(fullUrl, {
        ...fetchOptions,
        method: fetchOptions?.method || 'GET',
        headers,
        body,
        signal: abortController?.signal,
      });

      if (!response.ok) {
        // 尝试解析响应体获取详细错误信息
        let errorMessage = `HTTP error! status: ${response.status}`;
        try {
          const errorData = await response.json();
          errorMessage = errorData.message || errorData.error || errorMessage;
        } catch {
          // 无法解析 JSON，使用默认错误信息
        }
        throw new Error(errorMessage);
      }

      const reader = response.body?.getReader();
      const decoder = new TextDecoder();

      if (!reader) {
        throw new Error('No reader available');
      }

      let isEnd = false;
      while (!isEnd) {
        const { done, value } = await reader.read();
        if (done) {
          isEnd = true;
          onEnd?.();
          break;
        }
        const content = decoder.decode(value, { stream: true });
        onMessage?.(content);
      }
    } catch (error: any) {
      // 检查是否为取消操作
      if (error.name === 'AbortError') {
        // 请求被取消，不触发错误回调
        return;
      }
      // 触发错误回调
      if (onError) {
        onError(error);
      } else {
        // 没有错误回调时抛出错误
        throw error;
      }
    }
  }

  /** 设置国际化函数 */
  setI18n(fn: (key: string) => string) {
    this.t = fn;
    return this;
  }

  /** 设置消息提示函数 */
  setMessageHandler(fn: (type: 'error' | 'success', message: string) => void) {
    this.showMessage = fn;
    return this;
  }

  /** 设置重新认证函数 */
  setReAuthenticateHandler(fn: () => Promise<void>) {
    this.doReAuthenticate = fn;
    return this;
  }

  // ============================================================
  // 文件上传
  // ============================================================

  /** 设置 Refresh Token 获取函数 */
  setRefreshTokenGetter(fn: (endpoint: ApiEndpoint) => null | string) {
    this.getRefreshToken = fn;
    return this;
  }

  // ============================================================
  // 文件下载
  // ============================================================

  /** 设置 Token 刷新函数 */
  setRefreshTokenHandler(fn: () => Promise<string>) {
    this.doRefreshToken = fn;
    return this;
  }

  // ============================================================
  // SSE 流式请求
  // ============================================================

  /** 设置 Token 获取函数 */
  setTokenGetter(fn: (endpoint: ApiEndpoint) => null | string) {
    this.getToken = fn;
    return this;
  }

  /**
   * 文件上传
   */
  async upload<T = unknown>(
    url: string,
    data: UploadFileData,
    config?: RequestClientConfig,
    onProgress?: UploadProgressCallback,
  ): Promise<T> {
    const formData = new FormData();

    Object.entries(data).forEach(([key, value]) => {
      if (value !== undefined && value !== null) {
        if (Array.isArray(value)) {
          value.forEach((item, index) => {
            formData.append(`${key}[${index}]`, item);
          });
        } else {
          formData.append(key, value);
        }
      }
    });

    return this.post<T>(url, formData, {
      ...config,
      headers: {
        'Content-Type': 'multipart/form-data',
        ...config?.headers,
      },
      onUploadProgress: onProgress
        ? (progressEvent: { loaded: number; total?: number }) => {
            const { loaded, total } = progressEvent;
            if (total) {
              onProgress({
                loaded,
                total,
                percent: Math.round((loaded * 100) / total),
              });
            }
          }
        : undefined,
    });
  }

  // ============================================================
  // 辅助方法
  // ============================================================

  /** 绑定方法上下文 */
  private bindMethods() {
    this.get = this.get.bind(this);
    this.post = this.post.bind(this);
    this.put = this.put.bind(this);
    this.delete = this.delete.bind(this);
    this.request = this.request.bind(this);
    this.upload = this.upload.bind(this);
    this.download = this.download.bind(this);
    this.requestSSE = this.requestSSE.bind(this);
    this.postSSE = this.postSSE.bind(this);
  }
}

/**
 * 统一作用域工具函数
 *
 * 全平台共用，替代各模块分散的 getScopeColor/getScopeText/getScopeOptions。
 * 5 种作用域：admin_only / all_tenants / admin_and_all / admin_and_assigned / assigned_tenants
 */

import { $t } from '#/locales';

export interface ScopeConfig {
  color: string;
  icon: string;
  textKey: string;
}

/** 作用域配置表 */
export const SCOPE_CONFIG: Record<string, ScopeConfig> = {
  admin_only: {
    color: 'blue',
    icon: 'lucide:shield',
    textKey: 'common.scope.adminOnly',
  },
  all_tenants: {
    color: 'green',
    icon: 'lucide:users',
    textKey: 'common.scope.allTenants',
  },
  admin_and_all: {
    color: 'purple',
    icon: 'lucide:globe',
    textKey: 'common.scope.adminAndAll',
  },
  admin_and_assigned: {
    color: 'orange',
    icon: 'lucide:user-check',
    textKey: 'common.scope.adminAndAssigned',
  },
  assigned_tenants: {
    color: 'cyan',
    icon: 'lucide:user-plus',
    textKey: 'common.scope.assignedTenants',
  },
};

/** 获取 scope 颜色（Tag 使用） */
export function getScopeColor(scope: string | undefined): string {
  if (!scope) return 'default';
  return SCOPE_CONFIG[scope]?.color ?? 'default';
}

/** 获取 scope 文本（已翻译） */
export function getScopeText(scope: string | undefined): string {
  if (!scope) return '';
  const config = SCOPE_CONFIG[scope];
  return config ? $t(config.textKey) : scope;
}

/** 获取 scope 图标 */
export function getScopeIcon(scope: string | undefined): string {
  if (!scope) return 'lucide:help-circle';
  return SCOPE_CONFIG[scope]?.icon ?? 'lucide:help-circle';
}

export interface ScopeOption {
  label: string;
  value: string;
}

/**
 * 获取 scope 下拉选项
 *
 * @param allowedScopes 可选，限制返回的 scope 列表。不传则返回全部 5 种。
 */
export function getScopeOptions(allowedScopes?: string[]): ScopeOption[] {
  const scopes = allowedScopes ?? Object.keys(SCOPE_CONFIG);
  return scopes
    .filter((s) => s in SCOPE_CONFIG)
    .map((s) => ({
      label: $t(SCOPE_CONFIG[s]!.textKey),
      value: s,
    }));
}

/** 获取管理端可选的 scope 列表（排除 assigned_tenants，因为管理端不需要） */
export function getAdminScopeOptions(): ScopeOption[] {
  return getScopeOptions([
    'admin_only',
    'all_tenants',
    'admin_and_all',
    'admin_and_assigned',
    'assigned_tenants',
  ]);
}

/** 获取企业端可见的 scope 列表（企业端只能创建 all_tenants） */
export function getTenantScopeOptions(): ScopeOption[] {
  return getScopeOptions(['all_tenants']);
}

/**
 * Vite 自定义插件：novus-plugin-loader
 *
 * 仅负责将 backend/plugins/{name}/frontend/dist 复制到宿主输出目录 plugin-assets/
 * 以支持运行时 UMD 注入加载。插件源码不会被编译进宿主前端 bundle。
 */

import type { Plugin, ResolvedConfig } from 'vite';

import { cpSync, existsSync, mkdirSync, readdirSync, statSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const _dirname =
  typeof __dirname === 'undefined'
    ? fileURLToPath(new URL('.', import.meta.url))
    : __dirname;

interface PluginEntry {
  name: string;
  /** 插件 frontend/dist/ 绝对路径（有预编译产物时） */
  distDir: null | string;
}

/**
 * 扫描 backend/plugins/ 目录，发现所有有前端的插件
 */
function scanPlugins(pluginsDir: string): PluginEntry[] {
  if (!existsSync(pluginsDir)) return [];

  const entries: PluginEntry[] = [];

  for (const dirName of readdirSync(pluginsDir)) {
    const pluginRoot = join(pluginsDir, dirName);
    if (!statSync(pluginRoot).isDirectory()) continue;

    const distDir = join(pluginRoot, 'frontend', 'dist');
    const hasDist =
      existsSync(distDir) && existsSync(join(distDir, 'index.js'));

    if (hasDist) {
      entries.push({
        name: dirName,
        distDir: hasDist ? distDir : null,
      });
    }
  }

  return entries;
}

export interface NovusPluginsOptions {
  /**
   * backend/plugins/ 目录的绝对路径
   * 例如: E:/git_clone/novusai-saas-yudi/backend/plugins
   */
  pluginsDir?: string;
}

export function novusPluginsLoader(options: NovusPluginsOptions = {}): Plugin {
  let config: ResolvedConfig;
  let isBuild = false;

  if (!options.pluginsDir) {
    throw new Error(
      '[novus-plugins-loader] pluginsDir is required. ' +
        'Pass the absolute path to backend/plugins/ in vite.config.mts.',
    );
  }
  const pluginsDir = options.pluginsDir;

  const plugins: PluginEntry[] = scanPlugins(pluginsDir);

  return {
    name: 'novus-plugins-loader',
    enforce: 'post',

    configResolved(resolvedConfig) {
      config = resolvedConfig;
      isBuild = config.command === 'build';

      if (plugins.length > 0) {
        const names = plugins.map((p) => p.name);
        config.logger.info(
          `[novus-plugins] Found ${plugins.length} plugin dist package(s): ${names.join(', ')}`,
        );
      }
    },

    // build 模式：将只有 dist/ 的插件复制到构建输出目录
    writeBundle(outputOptions) {
      if (!isBuild) return;

      const outDir =
        outputOptions.dir ??
        (config.build?.outDir
          ? resolve(config.root, config.build.outDir)
          : resolve(config.root, 'dist'));

      for (const plugin of plugins) {
        if (!plugin.distDir) continue;
        const targetDir = join(outDir, 'plugin-assets', plugin.name);
        mkdirSync(targetDir, { recursive: true });
        cpSync(plugin.distDir, targetDir, { recursive: true });
        config.logger.info(
          `[novus-plugins] Copied dist/ for '${plugin.name}' → plugin-assets/${plugin.name}/`,
        );
      }
    },
  };
}

